(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0036.js"] = [{"id":"poem-ea94dbd910d37229b341cef8","title":"句","author":"林之奇","dynasty":"宋","verses":["耿耿一寸心，不能去庭闱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d015eff7-a03c-4d68-bae9-a4fee50adb21","tags":[]},{"id":"poem-ea965e1da49bb6644b85b93f","title":"閟宫","author":"佚名","dynasty":"先秦","verses":["閟宫有侐，实实枚枚。赫赫姜嫄，其德不回。上帝是依，无灾无害。","弥月不迟，是生后稷。降之百福。黍稷重穋，稙稚菽麦。奄有下国，俾民稼穑。","有稷有黍，有稻有秬。奄有下土，缵禹之绪。后稷之孙，实维大王。","居岐之阳，实始剪商。至于文武，缵大王之绪，致天之届，于牧之野。","无二无虞，上帝临女。敦商之旅，克咸厥功。王曰叔父，建尔元子，俾侯于鲁。","大启尔宇，为周室辅。乃命鲁公，俾侯于东。锡之山川，土田附庸。","周公之孙，庄公之子。龙旗承祀。六辔耳耳。春秋匪解，享祀不忒。","皇皇后帝！皇祖后稷！享以骍牺，是飨是宜。降福既多，周公皇祖，亦其福女。","秋而载尝，夏而楅衡，白牡骍刚。牺尊将将，毛炰胾羹。笾豆大房，万舞洋洋。","孝孙有庆。俾尔炽而昌，俾尔寿而臧。保彼东方，鲁邦是尝。不亏不崩，不震不腾。","三寿作朋，如冈如陵。公车千乘，朱英绿縢。二矛重弓。公徒三万，贝胄朱綅。","烝徒增增，戎狄是膺，荆舒是惩，则莫我敢承！俾尔昌而炽，俾尔寿而富。","黄发台背，寿胥与试。俾尔昌而大，俾尔耆而艾。万有千岁，眉寿无有害。","泰山岩岩，鲁邦所詹。奄有龟蒙，遂荒大东。至于海邦，淮夷来同。","莫不率从，鲁侯之功。保有凫绎，遂荒徐宅。至于海邦，淮夷蛮貊。","及彼南夷，莫不率从。莫敢不诺，鲁侯是若。天锡公纯嘏，眉寿保鲁。","居常与许，复周公之宇。鲁侯燕喜，令妻寿母。宜大夫庶士，邦国是有。","既多受祉，黄发儿齿。徂徕之松，新甫之柏。是断是度，是寻是尺。","松桷有舄，路寝孔硕，新庙奕奕。奚斯所作，孔曼且硕，万民是若。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-299","tags":[]},{"id":"poem-ea969c6d9af7c7a7e1f74a11","title":"白雀洞","author":"吕愿中","dynasty":"宋","verses":["洞中石燕可长生，白雀何因浪得名。","无限好山难买得，世间奚用孔方兄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1bfe8e9b-265a-464a-ac77-1270d6e6e391","tags":[]},{"id":"poem-eaa906d0c09c5e8d89b27b87","title":"湛露","author":"佚名","dynasty":"先秦","verses":["湛湛露斯，匪阳不晞。厌厌夜饮，不醉无归。","湛湛露斯，在彼丰草。厌厌夜饮，在宗载考。","湛湛露斯，在彼杞棘。显允君子，莫不令德。","其桐其椅，其实离离。岂弟君子，莫不令仪。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-173","tags":[]},{"id":"poem-eaa9cc40513a7a2170fb39e8","title":"同前换头","author":"萧德祥《小孙屠》","dynasty":"元","verses":["因为经过这里，蓦见伊形如鬼，逐惊荒寸心如水。","(生末)你分明，说此就理。","怎地胡推拒？到今日更难分理。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8679","tags":[]},{"id":"poem-eabdb978dd389bf7301e2e0a","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","verses":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d3357800-9021-4647-a0a0-98499a0ee3c5","tags":["宫怨","春天","写景","女子","唐诗三百首","五言律诗"]},{"id":"poem-eabee3f043d1658e0de51033","title":"乡试后自巩还田家因谢邻友见过之作","author":"卢象","dynasty":"唐","verses":["鸡鸣出东邑，马倦登南峦。","落日见桑柘，翳然丘中寒。","邻家多旧识，投暝来相看。","且问春税苦，兼陈行路难。","园场近阴壑，草木易凋残。","峰晴雪犹积，涧深冰已团。","浮名知何用，岁晏不成欢。","置酒共君饮，当歌聊自宽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-88a1c3c5-57ec-4b3b-8dac-f697baa68182","tags":[]},{"id":"poem-eac3efe232d8a277901f0719","title":"咏华清宫","author":"王建","dynasty":"唐","verses":["行尽江南数十程，晓风残月入华清。","朝元阁上西风急，都入长杨作雨声。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-詠華清宮","tags":[]},{"id":"poem-eac58e9e20ef5d3268f4fc2b","title":"吴王挽词  其一","author":"徐铉","dynasty":"宋","verses":["倏忽千龄尽，冥茫万事空。","青松洛阳陌，荒草建康宫。","道德遗文在，兴衰自古同。","受恩无补报，反袂泣途穷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4bc4f213-eb2c-4a89-a77c-39b6f9c04a17","tags":[]},{"id":"poem-ead180d0","title":"论诗·其二","author":"赵翼","dynasty":"清","verses":["李杜诗篇万口传，至今已觉不新鲜。","江山代有才人出，各领风骚数百年。"],"enabled":true,"collection":"历代名篇","source":"赵翼《瓯北集》诗《论诗五首》其二。","tags":["论诗"]},{"id":"poem-ead5b7031f176ae44b8cd833","title":"浣溪沙·绿树藏莺莺玉啼","author":"韦庄","dynasty":"五代","verses":["绿树藏莺莺玉啼，柳丝斜拂白铜堤，弄珠江上草萋萋。","日暮饮归何处客，绣鞍骢马一声嘶，满身兰麝醉如泥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-31","tags":[]},{"id":"poem-ead68e51610d824d318f08aa","title":"送曹同椅","author":"司空曙","dynasty":"唐","verses":["青春三十余，众艺尽无如。","中散诗传画，将军扇续书。","楚田晴下雁，江日暖游鱼。","惆怅空相送，欢游自此疎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ea112d09-8374-4aba-bdae-504d8c8d893c","tags":[]},{"id":"poem-eadad08f5957a51379a88ee6","title":"浣溪沙·一曲新词酒一杯","author":"晏殊","dynasty":"宋","verses":["一曲新词酒一杯。","去年天气旧亭台。","夕阳西下几时回。","无可奈何花落去，似曾相识燕归来。","小园香径独徘徊。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-159","tags":["宋词三百首"]},{"id":"poem-eadb7191352226404a3ce4de","title":"河满子·溪女送花随处","author":"张先","dynasty":"宋","verses":["溪女送花随处，沙鸥避乐分行。","游舸已如图障里，小屏犹画潇湘。","人面新生酒艳，日痕更欲春长。","衣上交枝斗色，钗头比翼相双。","片段落霞明水底，风纹时动妆光。","宾从夜归无月，千灯万火河塘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-413","tags":[]},{"id":"poem-eaddd4384ca6af9c6e11d01a","title":"句  其一二","author":"王予可","dynasty":"宋","verses":["凤环捧席带香屏，鲸杯倚伎和云卷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e431e7dc-9c11-4a6f-b1f4-9302c391e024","tags":[]},{"id":"poem-eade7f7a3391e593cd4b697a","title":"载芟","author":"佚名","dynasty":"先秦","verses":["载芟载柞，其耕泽泽。千耦其耘，徂隰徂畛。侯主侯伯，侯亚侯旅，侯彊侯以。","有嗿其馌，思媚其妇，有依其士。有略其耜，俶载南亩，播厥百谷。实函斯活，驿驿其达。","有厌其杰，厌厌其苗，绵绵其麃。载获济济，有实其积，万亿及秭。为酒为醴，烝畀祖妣，不洽百礼。","有飶其香。邦家之光。有椒其馨，胡考之宁。匪且有且，匪今斯今，振古如兹。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-289","tags":[]},{"id":"poem-eae20573fdef4854d4a59115","title":"闻叶蒙及第","author":"贯休","dynasty":"唐","verses":["忆昨送君诗，平人不用疑。","吾徒若不得，天道即应私。","尘土茫茫晓，麟龙草草骑。","相思不可见，又是落花时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a5400d94-a37f-4b08-9198-37ba84d6bb2c","tags":[]},{"id":"poem-eae2759be82a741bb9740cfb","title":"折槛行","author":"杜甫","dynasty":"唐","verses":["呜呼房魏不复见，秦王学士时难羡。","青衿胄子困泥涂，白马将军若雷电。","千载少似朱云人，至今折槛空嶙峋。","娄公不语宋公语，尚忆先皇容直臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-479f5094-eb0e-4254-a729-84bef1043f97","tags":[]},{"id":"poem-eaea2938a58758addda34ad0","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","dynasty":"唐","verses":["城上高楼接大荒，海天愁思正茫茫。","惊风乱飐芙蓉水，密雨斜侵薜荔墙。","岭树重遮千里目，江流曲似九廻肠。","共来百越文身地，犹自音书滞一乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3d26433c-a673-4094-8c83-cadb1b08412a","tags":["唐诗三百首","七言律诗","抒情","怀人"]},{"id":"poem-eaf86db2303d9c7efaa82dda","title":"上亭驿（题拟）","author":"罗隐","dynasty":"唐","verses":["细（《舆地纪胜》、《天中记》作「山」）雨霏微宿上亭，雨中因感（《舆地纪胜》、《天中记》作「想」）雨淋铃。","贵为天子犹魂断，穷著荷衣好涕零。","剑水多端何处去，巴猿无赖不堪听。","少年辛苦今飘荡，空（一作「深」）媿先生教聚萤。","（见宋王灼《碧鸡漫志》卷五。","）（按：《全唐诗》卷六六五据《天中记》收首二句，《全唐诗续补遗》卷十六据《舆地纪胜》卷一八六收前四句，均不全，今重录之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e8ecf538-d0df-4d4f-8bcc-d2ffca2cf958","tags":[]},{"id":"poem-eb0133cc9078d0a2a7bc6bbf","title":"河广","author":"佚名","dynasty":"先秦","verses":["谁谓河广？一苇杭之。谁谓宋远？跂予望之。","谁谓河广？曾不容刀。谁谓宋远？曾不崇朝。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-60","tags":[]},{"id":"poem-eb048593c2b95be4fa2fd3c3","title":"东归道中二首 一","author":"赵嘏","dynasty":"唐","verses":["平生事行役，今日始知非。","岁月老将至，江湖春未归。","传家有天爵，主祭用儒衣。","何必劳知己，无名亦息机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ea4cf60d-9597-42d1-86e4-5fd02035666f","tags":[]},{"id":"poem-eb073380a1f84eab2aa16f8a","title":"偈颂六十七首  其六六","author":"释原妙","dynasty":"宋","verses":["万法归一一何归，只贵惺惺著意疑。","疑到情忘心绝处，金乌夜半彻天飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-42304028-88f1-4025-a26a-19a948e0992c","tags":[]},{"id":"poem-eb1b5f0df7b0d6a07fc71246","title":"菩萨蛮·春来晴雨常相半","author":"韩淲","dynasty":"宋","verses":["春来晴雨常相半。","水光风力花撩乱。","山北与山南。","行歌或再三。","诵君诗过日。","才大真盘屈。","寿我敢言酬。","相望亦饮不。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-485","tags":[]},{"id":"poem-eb1fddb9e22d1e84f0cbe41d","title":"题诠律师院","author":"张乔","dynasty":"唐","verses":["院凉松雨声，相对有山情。","未许谿边老，犹思岳顶行。","纱灯留火细，石井灌瓶清。","欲问吾师外，何人得此生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bff8dfde-34fb-410c-8cbe-90601ca2f855","tags":[]},{"id":"poem-eb202029b2fc0020e5e9ba98","title":"贺新郎·睡起啼莺语","author":"叶梦得","dynasty":"宋","verses":["睡起啼莺语。","掩青苔、房栊向晚，乱红无数。","吹尽残花无人见，惟有垂杨自舞。","渐暖霭、初回轻暑。","宝扇重寻明月影，暗尘侵、尚有乘鸾女。","惊旧恨，遽如许。","江南梦断横江渚。","浪黏天、葡萄涨绿，半空烟雨。","无限楼前沧波意，谁采苹花寄取。","但怅望、兰舟容与。","万里云帆何时到，送孤鸿、目断千山阻。","谁为我，唱金缕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-263","tags":["宋词三百首"]},{"id":"poem-eb33f325081a36b04a4dd271","title":"日出行","author":"李贺","dynasty":"唐","verses":["白日下昆仑，发光如舒丝。","徒照葵藿心，不照游子悲。","折折黄河曲，日从中央转。","旸谷耳曾闻，若木眼不见。","奈尔铄石，胡为销人，羿弯弓属矢那不中。","足令久不得奔，讵教晨光夕昏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d0e7182f-cc73-4de5-b3c2-d891d0034686","tags":["黄河"]},{"id":"poem-eb3c3414e1522a6f9a4ac511","title":"同颜六少府旅宦秋中之作","author":"高适","dynasty":"唐","verses":["传君昨夜怅然悲，独坐新斋木落时。","逸气旧来凌燕雀，高才何得混妍媸。","迹留黄绶人多叹，心在青云世莫知。","不是鬼神无正直，从来州县有瑕疵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-15abc23d-8849-43a1-aeb8-28eebdaac884","tags":[]},{"id":"poem-eb4ecec909421f0f55be10e7","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)三更漏转，寒雁声嘹呖。","半明灭灯火煤，寻思这般沉疾，这般狼狈。","相别到今，到今凶吉未知！冷落空房，药食准调理？床儿上怎生，怎生独自个睡？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3027","tags":[]},{"id":"poem-eb50eb29f7c6e2a8297287b7","title":"别江上一二友生","author":"谭用之","dynasty":"宋","verses":["国风千载务重华，须逐浮云背若耶。","无地可归堪种玉，有天教上且乘槎。","白纶巾卸苏门月，红锦衣裁御苑花。","他日成都却回首，东山看取谢鲲家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-277b660b-69e3-4934-b711-e38f3bd554dd","tags":[]},{"id":"poem-eb515709180b6a853f9c11a7","title":"观李固请司马弟山水图","author":"杜甫","dynasty":"唐","verses":["方丈浑连水，天台总映云。","人间长见画，老去限空闻。","范蠡舟偏小，王乔鹤不群。","此生随万物，何处出尘氛。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-觀李固請司馬弟山水圖","tags":[]},{"id":"poem-eb562f0ebbfb5d43094f88bb","title":"御街行·街南绿树春饶絮","author":"晏几道","dynasty":"宋","verses":["街南绿树春饶絮。","雪满游春路。","树头花艳杂娇云，树底人家朱户。","北楼闲上，疏帘高卷，直见街南树。","阑干倚尽犹慵去。","几度黄昏雨。","晚春盘马踏青苔，曾傍绿阴深驻。","落花犹在，香屏空掩，人面知何处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-32","tags":["宋词三百首"]},{"id":"poem-eb5d71a2a15526549abbcfd4","title":"小游仙诗九十八首 二十九","author":"曹唐","dynasty":"唐","verses":["汗漫真游实可奇，人间天上几人知。","周王不信长生话，空使苌弘碧泪垂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c22cc759-e53c-43fe-a887-373ba46ff76d","tags":[]},{"id":"poem-eb5e2d5428e13c9907397c69","title":"采桑子·群芳过后西湖好","author":"欧阳修","dynasty":"宋","verses":["群芳过后西湖好，狼籍残红。","飞絮蒙蒙。","垂柳阑干尽日风。","笙歌散尽游人去，始觉春空。","垂下帘栊。","双燕归来细雨中。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-169","tags":["宋词三百首","西湖"]},{"id":"poem-eb71915117a17b84d65b3505","title":"生查子·荷花人面红","author":"李石","dynasty":"宋","verses":["荷花人面红，月影波心见。","扇子倒拈来，敲落红香片。","窗下翦灯花，今日眉深浅。","留得镜中看，蹙破春山远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-250","tags":[]},{"id":"poem-eb7434931b58cc436a7d9e85","title":"句","author":"卢嵩","dynasty":"唐","verses":["岁晏以为期。","（《韦江州集》卷五有韦应物作《酬卢嵩秋夜见寄五韵》，诗末原注曰：「卢诗云岁晏以为期之句。","」按卢诗不传，此虽只句，亦弥足珍。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8bc510c5-85d8-4c7f-b20f-69f3bedc1553","tags":[]},{"id":"poem-eb844076dd666782efa09f65","title":"更漏子 其五","author":"温庭筠","dynasty":"唐","verses":["背江楼，临海月，城上角声呜咽。","堤柳动，岛烟昏，两行征雁分。","京口路，归帆渡，正是芳菲欲度。","银烛尽，玉绳低，一声村落鸡。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-18","tags":[]},{"id":"poem-eb8b263abe2b5b57326702c4","title":"别弟缙后登青龙寺望蓝田山","author":"王维","dynasty":"唐","verses":["陌上新离别，苍茫四郊晦。","登高不见君，故山复云外。","远树蔽行人，长天隐秋塞。","心悲宦游子，何处飞征盖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ae1402ee-2613-4d6b-9549-ab7ce6d368f6","tags":[]},{"id":"poem-eb936430f7e79cd142487965","title":"贞娘墓歌","author":"米芾","dynasty":"宋","verses":["何不学仙冢累累，白杨西郭阴风悲。","虎邱一叩贞娘墓，薜荔援墙委兰露。","千岁蒙茸几树花，夜飘鬼火晓啼鸦。","向怜挟瑟弹清月，犹忆吹箫乘彩霞。","吴阊少年往来道，黛蛾钗燕谁能好。","酒滴春云梦不消，泉声幽咽钟声老。","陌上行游缓缓归，昨日红颜今日非。","东望阖闾穿葬处，玉凫将化湛卢飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e725023c-c166-4805-9b77-c180aa2ac0e0","tags":[]},{"id":"poem-eb954294693bc1100837241a","title":"邙山","author":"沈佺期","dynasty":"唐","verses":["北邙山上列坟茔，万古千秋对洛城。","城中日夕歌钟起，山上唯闻松栢声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5909e17d-a969-44ef-8e09-383f21387492","tags":[]},{"id":"poem-eb9e5abdc33dd4928784efee","title":"神龙初废逐南荒途出郴口北望苏耽山","author":"沈佺期","dynasty":"唐","verses":["少曾读仙史，知有苏耽君。","流望来南国，依然会昔闻。","泊舟问耆老，遥指孤山云。","孤山郴郡北，不与众山群。","重崖下萦映，嶛峣上乣纷。","碧峰泉附落，红壁树傍分。","选地今方尔，升天因可云。","不才予窜迹，羽化子遗芬。","将览成麟凤，旋惊御鬼文。","此中迷出处，含思独氛氲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b525f817-8750-43db-bdfc-7366b7ef5936","tags":[]},{"id":"poem-ebac4ccf2a7216d099cc3380","title":"阮郎归·小楼秋霁碧阑干","author":"韩淲","dynasty":"宋","verses":["小楼秋霁碧阑干。","中人初薄寒。","霜风吹我到湖山。","平林斜照残。","空阔里，有无间。","牵萝翠袖闲。","篮舆兴尽却愁还。","断肠歌未阑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-430","tags":[]},{"id":"poem-ebac596989691f3dc1faeca3","title":"醉中真・浣溪沙·不信芳春厌老人","author":"贺铸","dynasty":"宋","verses":["不信芳春厌老人。","老人几度送春归。","惜春行乐莫辞频。","巧笑艳歌皆我意，恼花颠酒拼君嗔。","物情惟有醉中真。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-73","tags":["宋词三百首"]},{"id":"poem-ebaec90cbb6856f5ff1d6e40","title":"胡笳十八拍 第三拍","author":"李纲","dynasty":"宋","verses":["千乘万骑出咸阳，百官跣足随天王。","翠华摇摇行复止，黄尘暗天道路长。","金盘玉筯无消息，色难腥腐飡风香。","晚将末契托年少，遂令再往之计堕渺茫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-73dbeee3-81d4-4b32-b8c8-3be7aba1cf26","tags":[]},{"id":"poem-ebb5d726222f51527f6484ee","title":"新楼诗二十首 水寺","author":"李绅","dynasty":"唐","verses":["烟波野寺经过处，水国苍茫梦想中。","云散浦间江月迥，日曛洲渚海潮通。","坐看鱼鸟沈浮远，静见楼台上下同。","闻道化城方便喻，只应从此到龙宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3875128a-b5d2-4d34-810b-d54f54f8fb56","tags":[]},{"id":"poem-ebb6ec0780139b4ddff39291","title":"春日杂兴十五首  其一一","author":"华镇","dynasty":"宋","verses":["迢递长江表，崎岖青障间。","瑞草杂野卉，吐秀莫穷看。","馥鬰谁与奇，细碎如等闲。","荆榛共荣悴，樵牧几摧残。","殊乡采嘉声，千里辏名园。","轻舟走雕槛，文砌荐朱栏。","芳华未盈枝，倾都已酡颜。","疏丛乏葱蒨，薄采媿朱殷。","珍赏占芳时，野客更旧观。","试问蜂和蝶，何如蕙与兰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e8228eea-0d99-4e95-be1d-0102254c3a7b","tags":["长江"]},{"id":"poem-ebbe680b16c2fbfdb0370d4d","title":"渔父·浪花有意千里雪","author":"李煜","dynasty":"五代","verses":["浪花有意千里雪，桃花无言一队春。","一壶酒，一竿身，快活如侬有几人。","一棹春风一叶舟，一纶茧缕一轻钩。","花满渚，酒满瓯，万顷波中得自由。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-44","tags":[]},{"id":"poem-ebc52fe2389fad537cb99353","title":"生查子·子月到盘洲","author":"洪适","dynasty":"宋","verses":["子月到盘洲，日影长添线。","水退露溪痕，风急寒芦战。","终日倚枯藤，细看浮云变。","洲畔有圆沙，招尽云边雁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-729","tags":[]},{"id":"poem-ebcb2f8d49814a10fdcac0ea","title":"三姝媚·烟光摇缥瓦","author":"史达祖","dynasty":"宋","verses":["烟光摇缥瓦。","望晴檐多风，柳花如洒。","锦瑟横床，想泪痕尘影，凤弦常下。","倦出犀帷，频梦见、王孙骄马。","讳道相思，偷理绡裙，自惊腰衩。","惆怅南楼遥夜。","记翠箔张灯，枕肩歌罢。","又入铜驼，遍旧家门巷，首询声价。","可惜东风，将恨与、闲花俱谢。","记取崔徽模样，归来暗写。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-182","tags":["宋词三百首"]},{"id":"poem-ebd1fa7e2f869d4291205d16","title":"西塞山下回舟作","author":"陶岘","dynasty":"唐","verses":["匡庐旧业是谁主，吴越新居安此生。","白发数茎归未得，青山一望计还成。","鸦翻枫叶夕阳动，鹭立芦花秋水明。","从此舍舟何所诣，酒旗歌扇正相迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6b14551d-2650-480a-8bfd-4e38ec1c4f9e","tags":["庐山"]},{"id":"poem-ebd4193d02f540b1bcad5d05","title":"挽严四府君","author":"华镇","dynasty":"宋","verses":["岁事时无失，先畴手自耘。","克家亲有养，投老意弥勤。","方羡高年庆，旋惊白日曛。","可怜坟上土，仍占垅头云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1b35cc18-64a7-4059-9752-04b2daf56afb","tags":[]},{"id":"poem-ebd74783954816c7efcb3358","title":"峡哀 四","author":"孟郊","dynasty":"唐","verses":["峡乱鸣清磬，产石为鲜鳞。","喷为腥雨涎，吹作黑井身。","怪光闪众异，饿劒唯待人。","老肠未曾饱，古齿崭岩嗔。","嚼齿三峡泉，三峡声龂龂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1ed92763-9ec1-4a40-a4fc-13fd46f584c4","tags":[]},{"id":"poem-ebe1ef5256f7826df61da91e","title":"送孙二","author":"王维","dynasty":"唐","verses":["郊外谁相送，夫君道术亲。","书生邹鲁客，才子洛阳人。","祖席依寒草，行车起暮尘。","山川何寂寞，长望泪沾巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f5a33e9a-00ff-486e-b4e4-d52eba32f9f9","tags":[]},{"id":"poem-ebe2e57dc3a5b8b2505943db","title":"浣溪沙·凤髻抛残秋草生","author":"纳兰性德","dynasty":"清","verses":["凤髻抛残秋草生。","高梧湿月冷无声。","当时七夕记深盟。","信得羽衣传钿合，悔教罗袜葬倾城。","人间空唱雨淋铃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-28","tags":[]},{"id":"poem-ebed8220cc04a8eca53ee18b","title":"大环着","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(外)那一日江道，那一日江道，得梦蹊跷。","灵神对吾曾说道，见佳人果然声韵高。","投水江心早，梢公救捞，问真情取覆言词了。","留为义女，带同临任所福州道。","(合)怎知今日，夫妻母子，子母团圆，再得重相好。","腰金衣紫还乡，大家齐欢笑，百世永谐老。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8352","tags":[]},{"id":"poem-ebf63b184502f053e07c3389","title":"敦煌廿咏（并序） 十八、相似树咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["两树夹招提，三春引影低。","叶中微有字，阶下已成蹊。","含气同修短，分条德且齐。","不容凡鸟坐，应欲俟栖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9711d6f5-569b-48c1-b3c0-7d5c37e34893","tags":[]},{"id":"poem-ebfafa5d1c33d8a8c5c19cb6","title":"赠张均员外","author":"卢象","dynasty":"唐","verses":["公门世绪昌，才子冠裴王。","出自平津邸，还为吏部郎。","神仙余气色，列宿动辉光。","夜直南宫静，朝趋北禁长。","时人归水镜，明主赐衣裳。","翰苑飞鹦鹉，天池待凤凰。","承欢畴日顾，未纪后时伤。","去去图南远，微才幸不忘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-67d60c2f-ad7a-4101-a782-7e9cb01e570e","tags":[]},{"id":"poem-ebff65bf6a6ad60069a35e6e","title":"醉花间·深相忆","author":"毛文锡","dynasty":"五代","verses":["深相忆，莫相忆，相忆情难极。","银汉是红墙，一带遥相隔。","金盘珠露滴，两岸榆花白。","风摇玉佩清，今夕为何夕。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-22","tags":[]},{"id":"poem-ec02b23597e5c1adcac8bdf6","title":"生查子·相见稀","author":"张泌","dynasty":"五代","verses":["相见稀，喜相见，相见还相远。","檀画荔枝红，金蔓晴蜓软。","鱼雁疏，芳信断，花落庭阴晚。","可怜玉肌肤，消瘦成慵懒。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-43","tags":[]},{"id":"poem-ec076f0d9f42b6b168787cb8","title":"嵩山十志十首 其十","author":"卢鸿一","dynasty":"唐","verses":["水碧色兮石金光，滟熠熠兮濙湟湟。","泉葩映兮烟茑临，红灼灼，翠阴阴。","翠相鲜兮金碧潭，霜天洞兮烟景涵。","有幽人兮好冥绝，炳其焕兮凝其洁，悠悠千古长不灭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7e6bfc79-bfdb-4645-a08b-855124e0e02b","tags":[]},{"id":"poem-ec09826ee79507328c421945","title":"法寿乐歌","author":"赵文","dynasty":"宋","verses":["西云垂天飞流黄，宝鬘百万随风扬，帝居摩醯首罗乡。","采女如花侍帝旁，珠啼玉唾天花香，澹然神情无世妆。","下视邢尹纷醒狂，梵呗琅琅出清吭，天庖供馔荐豆觞。","帝饮食之寿以康，恒沙世界俱来王，天王神圣臣忠良。","春风万里酣耕桑，雨滴可数海可量，无有能知法寿长。","梵天释帝万亿岁，岁岁寿杯天下醉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b2b575c3-ac6b-44ef-91fb-9d2bf35929af","tags":[]},{"id":"poem-ec0b53a5698c9429c57dd9a2","title":"宋氏五女","author":"王建","dynasty":"唐","verses":["五女誓终养，贞孝内自持。","兔丝自萦纡，不上青松枝。","晨昏在亲傍，闲则读书诗。","自得圣人心，不因儒者知。","少年绝音华，贵绝父母词。","素钗垂两髦，短窄古时衣。","行成闻四方，征诏环珮随。","同时入皇宫，联影步玉墀。","乡中尚其风，重为修茅茨。","圣朝有良史，将此为女师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6f2cc792-642c-4d3a-8113-c9f46ea1fd7f","tags":[]},{"id":"poem-ec11161cf29721f25657d358","title":"初冬从幸汉故青门应制","author":"沈佺期","dynasty":"唐","verses":["汉王建都邑，渭水对青门。","朝市俱东逝，坟陵共北原。","荒凉萧相阙，芜没邵平园。","全盛今何在，英雄难重论。","故基仍岳立，遗堞尚云屯。","当极土功壮，安知人力烦。","天游戒东首，怀昔驻龙轩。","何必金汤固，无如道德藩。","微臣谅多幸，参乘偶殊恩。","预此陈古事，敢奏兴亡言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0bc62fb4-dd3d-40ed-8ee5-11dafbefe8a0","tags":[]},{"id":"poem-ec12f9a954c0f0632e847b77","title":"奉和喜雪应制","author":"徐安贞","dynasty":"唐","verses":["两宫斋祭近登临，雨雪纷纷天昼阴。","祗为经寒无瑞色，顿教正月满春林。","蓬莱北上旌门暗，花萼南归马迹深。","自有三农歌帝力，还将万庾荅尧心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-46a4f158-95b7-46f9-90f9-78bc571ae001","tags":[]},{"id":"poem-ec1bf7d1cd9e5322c2d95511","title":"句","author":"豆卢岑","dynasty":"唐","verses":["隔门借问人谁在，一树桃花笑不应。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f3e4c4ac-2277-4ca8-9e67-0e5d0012f9a4","tags":[]},{"id":"poem-ec1d9e9d5a34ec3c6b3454df","title":"春秋战国门 管仲","author":"周昙","dynasty":"唐","verses":["美酒浓馨客要沽，门深谁敢强提壶。","苟非贤主询贤士，肯信沽人畏子獹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bbacad07-59a8-4ac8-9f02-3fb689acb3a3","tags":[]},{"id":"poem-ec2108ac86aa0335a759f354","title":"句","author":"皮公弼","dynasty":"宋","verses":["壁山老守似僧家，无酒无歌岁华。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-742e31bb-322b-493a-bbad-4da3a4c589a9","tags":[]},{"id":"poem-ec2b656a4e3b42e691509c40","title":"大礼毕皇帝御丹凤门改元建中大赦","author":"李益","dynasty":"唐","verses":["大明曈曈天地分，六龙负日升天门。","凤凰飞来衔帝箓，言我万代金皇孙。","灵鸡鼓舞承天赦，高翔百尺垂朱幡。","宸居穆清受天历，建中甲子合上元。","昊穹景命即已至，王事乃可酬乾坤。","升中告成答玄贶，泥金检玉昭鸿恩。","云亭之事略可记，七十二君宁独尊。","小臣欲上封禅表，久而未就归文园。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-53507dd1-ecdc-459b-ad7f-18951aa1751b","tags":[]},{"id":"poem-ec3a98a0ed5651c88466ab73","title":"渔父","author":"贯休","dynasty":"唐","verses":["一叶一竿竹，眉须雪欲零。","陆应无祖业，香必是伊腥。","儿亦名鱼鹧，歌称我洞庭。","回头深自媿，旧业近沧溟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f70914bd-6189-41db-b71d-0150db9ea2f9","tags":["洞庭湖"]},{"id":"poem-ec43d8d7c0ac9f2366ac9229","title":"乌夜啼","author":"无名氏《张协状元》","dynasty":"元","verses":["听得你鸡鸣起。","(旦出接)扑簌簌泪两下。","(末)你郎今挂绿在京华。","(旦)音书断，没成虚假。","(合)不免辞庙去，京里试寻它。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2645","tags":[]},{"id":"poem-ec4642f35c1c82d33c772747","title":"劝农","author":"江万里","dynasty":"宋","verses":["农岂犹需我劝农，且从人意卜年丰。","喜闻布谷声声急，莫为催科处处穷。","父老来前吾语汝，官民相近古遗风。","欲知太守乐其乐，乐在田家欢笑中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-63edbf70-0a37-48a5-9332-5b70d081fb5d","tags":[]},{"id":"poem-ec46d2d662a512e256bbd48d","title":"满庭芳·堠雪翻鸦","author":"纳兰性德","dynasty":"清","verses":["堠雪翻鸦，河冰跃马，惊风吹度龙堆。","阴磷夜泣，此景总堪悲。","待向中宵起舞，无人处、那有村鸡。","只应是，金笳暗拍，一样泪沾衣。","须知今古事，棋枰胜负，翻覆如斯。","叹纷纷蛮触，回首成非。","剩得几行青史，斜阳下、断碣残碑。","年华共，混同江水，流去几时回。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-99","tags":[]},{"id":"poem-ec4c95415086415e4b613ed0","title":"腊茶并三诗送李元诚  其一","author":"陈造","dynasty":"宋","verses":["池鱼千里磨蚁旋，人生出处俱可怜。","束书结邻晏溪侧，淮安一寤三十年。","积今成古阅飞电，我与昔人同此叹。","悲欢离合置勿论，且喜重逢各彊健。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e96d1a6f-1291-435c-8e8f-73ee646a3016","tags":[]},{"id":"poem-ec5c4007ba490636f35a6bae","title":"菩萨蛮·隔花才歇帘纤雨","author":"纳兰性德","dynasty":"清","verses":["隔花才歇帘纤雨，一声弹指浑无语。","梁燕自双归，长条脉脉垂。","小屏山色远，妆薄铅华浅。","独自立瑶阶，透寒金缕鞋。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-215","tags":[]},{"id":"poem-ec604628b21882b7fc9c28d4","title":"古意九首 三","author":"贯休","dynasty":"唐","verses":["美人如游龙，被服金鸳鸯。","手把古刀尺，在彼白玉堂。","文章深掣曳，珂珮鸣丁当。","好风吹桃花，片片落银床。","何妨学羽翰，远逐朱鸟翔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-68c2b127-eda7-498d-828e-46271de7d98f","tags":[]},{"id":"poem-ec71ea5b3bd7e95ff48ce7b8","title":"青玉案·三年枕上吴中路","author":"苏轼","dynasty":"宋","verses":["三年枕上吴中路。","遣黄耳、随君去。","若到松江呼小渡。","莫惊鸥鹭，四桥尽是，老子经行处。","辋川图上看春暮。","常记高人右丞句。","作个归期天已许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-46","tags":["宋词三百首","西湖"]},{"id":"poem-ec728dcd4eb72223c1f97028","title":"颂古三十一首  其一九","author":"释安永","dynasty":"宋","verses":["见兔放鹰，因邪打正。","脚未跨门，直须猛省。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2f20d295-79ca-4ce6-bc1d-75cbe6ffa4e7","tags":[]},{"id":"poem-ec7b99611d4ce84e5014e055","title":"送费[炼]师供奉赴上都","author":"姚鹄","dynasty":"唐","verses":["缩地周游不计程，古今应只有先生。","已同化鹤临华表，又见骖龙向玉清。","萝磴静攀云共过，雪坛当醮月孤明。","无因相逐朝天帝，空羡烟霞得送迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2b182d19-23c0-49cc-a663-14344b7e22e9","tags":[]},{"id":"poem-eca2aa1ff7e55aa3f5a8f51f","title":"杂兴六首 三","author":"皎然","dynasty":"唐","verses":["谁高齐公子，泣听雍门琴。","死且何足伤，殊非达人心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c320b71e-2a0e-4b3b-bd6b-c9843bc7ee05","tags":[]},{"id":"poem-ecad93cc8832d5b02e4dcacf","title":"武","author":"佚名","dynasty":"先秦","verses":["于皇武王！无竞维烈。允文文王，克开厥后。嗣武受之，胜殷遏刘，耆定尔功。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-284","tags":[]},{"id":"poem-ecb0bb13e5d7eef7c2344d9d","title":"西施捧心图","author":"赵崇嶓","dynasty":"宋","verses":["吴苑风光越水春，两山眉里笑颦分。","腹心别有堪忧处，狂杀君王藐不闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1ccd371e-987d-4075-aa3a-a4a45dd8bed6","tags":[]},{"id":"poem-ecb9687ced46565765185009","title":"洛阳春望","author":"鲍溶","dynasty":"唐","verses":["五凤楼南望洛阳，龙门回合抱苍苍。","受朝前殿云霞煗，封岳行宫草木香。","四海为家知德盛，二京有宅卜年长。","东人犹忆时巡礼，愿觐元和日月光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1a1692c9-24e3-447f-a7e8-0e4d50eeedab","tags":[]},{"id":"poem-ecd338c52610504de60dba79","title":"病僧二首 二","author":"刘言史","dynasty":"唐","verses":["空林衰病卧多时，白发从成数寸丝。","西行却过流沙日，枕上寥寥心独知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cb58a591-d3a0-4a5e-855d-548921296e29","tags":[]},{"id":"poem-ecdf69108a3d7ede45fc5a4c","title":"送孟宾于","author":"马致恭","dynasty":"宋","verses":["曾闻洛下缀神仙，火树南栖几十年。","白首自忻丹桂在，诗名已得四方传。","行随秋渚将归雁，吟傍梅花欲雪天。","今日还家莫惆怅，不同初上渡头船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5c781bb8-c50a-41d1-99be-232fd4ed4a62","tags":[]},{"id":"poem-ece05a1080507d804fe82b45","title":"书怀","author":"张籍","dynasty":"唐","verses":["自小信成疎嬾性，人间事事总无功。","别从仙客求方法，时到僧家问苦空。","老大登朝如梦里，贫穷作活似村中。","未能即便休官去，惭愧南山采药翁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-18a94893-e46a-4a0b-a892-934276cd8286","tags":[]},{"id":"poem-ece3a3156b5bb153cf81e11d","title":"句  其一○","author":"王予可","dynasty":"宋","verses":["帘卷绿阴花外月，玉山冰雪醉扶翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-dd2c7f98-cd55-42b8-bc87-3974669025e0","tags":[]},{"id":"poem-ecec5fd67f7a3fc602552aaa","title":"咏史诗 圯桥","author":"胡曾","dynasty":"唐","verses":["庙算张良独有余，少年逃难下邳初。","逡巡不进泥中履，争得先生一卷书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8731b138-40af-4c4c-9d09-89877e623c35","tags":[]},{"id":"poem-ecee536ccc0d4ebdf05cf576","title":"铜雀妓","author":"郑愔","dynasty":"唐","verses":["日斜漳浦望，风起邺台寒。","玉座平生晚，金尊妓吹阑。","舞余依帐泣，歌罢向陵看。","萧索松风暮，愁烟入井阑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7c9f47d1-81e7-4cf0-bd23-0e8f7e76351f","tags":[]},{"id":"poem-ecf7e4b3310a98939e43b152","title":"渔夫舞·济涉还渠渔父子","author":"史浩","dynasty":"宋","verses":["济涉还渠渔父子。","生涯只在烟波里。","练静忽然风又起。","赢得底。","吹来别浦看桃李。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-40","tags":[]},{"id":"poem-ecfb58b17eaa26920025bbe5","title":"长干行","author":"崔颢","dynasty":"唐","verses":["君家在何处？妾住在横塘。","停船暂借问，或恐是同乡。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-長幹行","tags":[]},{"id":"poem-ed00d6725c8c17f3fff688ab","title":"郊庙歌辞 祭方丘乐章 肃和","author":"褚亮","dynasty":"唐","verses":["至矣坤德，皇哉地祇。","开元统纽，合大承规。","九宫肃列，六典相仪。","永言配命，长保无亏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-44cc1286-e8d7-4374-8cb6-96067c6a09fa","tags":[]},{"id":"poem-ed095ddbb947c92dba614177","title":"寻梅·今年早觉花信蹉","author":"沈蔚","dynasty":"宋","verses":["今年早觉花信蹉。","想芳心、未应误我。","一月小径几回过。","始朝来寻见，雪痕微破。","眼前大抵情无那。","好景色、只消些个。","春风烂熳却且可。","是而今、枝上一朵两朵。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-980","tags":[]},{"id":"poem-ed102b44e21b953db05fb302","title":"浣溪沙·帘下三间出寺墙","author":"薛昭蕴","dynasty":"五代","verses":["帘下三间出寺墙，满街垂杨绿阴长，嫩红轻翠间浓妆。","瞥地见时犹可可，却来闲处暗思量，如今情事隔仙乡。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-30","tags":[]},{"id":"poem-ed12d4052ff8f0b3cb3b461e","title":"杨柳枝·馆娃宫外邺城西","author":"温庭筠","dynasty":"唐","verses":["馆娃宫外邺城西，远映征帆近拂提。","系得王孙归意切，不关芳草绿萋萋。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-33","tags":[]},{"id":"poem-ed202f8d7cf1d135cd710d09","title":"李夫人歌","author":"李贺","dynasty":"唐","verses":["紫皇宫殿重重开，夫人飞入琼瑶台。","绿香绣帐何时歇，青云无光宫水咽。","翩联桂花坠秋月，孤鸾惊啼商丝发。","红壁阑珊悬珮珰，歌台小妓遥相望。","玉蟾滴水鸡人唱，露华兰叶参差光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7bd22cdb-d78e-4bd5-af73-b08be1974bbe","tags":[]},{"id":"poem-ed2d5cc624df4773096ca9c6","title":"高阳台·频听银签","author":"韩","dynasty":"宋","verses":["频听银签，重燃绛蜡，年华衮衮惊心。","饯旧迎新，能消几刻光阴。","老来可惯通宵饮，待不眠、还怕寒侵。","掩清尊。","多谢梅花，伴我微吟。","邻娃已试春妆了，更蜂腰簇翠，燕股横金。","勾引东风，也知芳思难禁。","朱颜那有年年好，逞艳游、赢取如今。","恣登临。","残雪楼台，迟日园林。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-50","tags":["宋词三百首"]},{"id":"poem-ed340fce8f32155b94a32938","title":"守岁二首 二","author":"卢仝","dynasty":"唐","verses":["老来经节腊，乐事甚悠悠。","不及儿童日，都卢不解愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5e5b0860-39b1-46ee-aa71-d772bd24bbc5","tags":[]},{"id":"poem-ed3f510f391970874bd00e0a","title":"胡捣练","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦上)兄嫂没前程，罚我挨磨到天明。","把我孩儿撇在水，火公救不见回音。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8961","tags":[]},{"id":"poem-ed435575b54449c9537dbe5c","title":"应天长·别来半岁音书绝","author":"韦庄","dynasty":"五代","verses":["别来半岁音书绝，一寸离肠千万结。","难相见，易相别，又是玉楼花似雪。","暗相思，无处说，惆怅夜来烟月。","想得此时情切，泪沾红袖黦。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-42","tags":[]},{"id":"poem-ed4cab031592bb1fbac27d49","title":"杕杜","author":"佚名","dynasty":"先秦","verses":["有杕之杜，有睆其实。王事靡盬，继嗣我日。日月阳止，女心伤止，征夫遑止。","有杕之杜，其叶萋萋。王事靡盬，我心伤悲。卉木萋止，女心悲止，征夫归止！","陟彼北山，言采其杞。王事靡盬，忧我父母。檀车幝幝，四牡痯痯，征夫不远！","匪载匪来，忧心孔疚。斯逝不至，而多为恤。卜筮偕止，会言近止，征夫迩止！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-168","tags":[]},{"id":"poem-ed5cce89a588f6eb7607d0c6","title":"饮马长城窟","author":"王建","dynasty":"唐","verses":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄踪未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a2d88511-cac0-434e-a102-792458bc3af5","tags":[]},{"id":"poem-ed5d2f02323ff6371e53892b","title":"山居","author":"李涉","dynasty":"唐","verses":["一从身世两相遗，往往关门到午时。","想得俗流应大笑，不知年老识便宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d02e730c-f618-46e8-9441-0f2f38b50878","tags":[]},{"id":"poem-ed5dba11256820c92f229adf","title":"衮第三","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["那更老亲，鬓垂白，筋力皆癯瘁。","形只影单，无弟兄，谁奉侍？况隔千山万水，生死存亡，虽有音书难寄。","最可悲，他甘旨不供，我食禄有愧。","(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5025","tags":[]},{"id":"poem-ed60c7a063fe89c2a1ea0b76","title":"贺新郎·乳燕飞华屋","author":"苏轼","dynasty":"宋","verses":["乳燕飞华屋。","悄无人、桐阴转午，晚凉新浴。","手弄生绡白团扇，扇手一时似玉。","渐困倚、孤眠清熟。","帘外谁来推绣户，枉教人、梦断瑶台曲。","又却是，风敲竹。","石榴半吐红巾蹙。","待浮花、浪蕊都尽，伴君幽独。","艳一枝细看取，芳心千重似束。","又恐被、秋风惊绿。","若待得君来向此，花前对酒不忍触。","共粉泪，两蔌蔌。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-42","tags":["宋词三百首"]},{"id":"poem-ed71c1e8e00bef84e856b568","title":"问岳禅师疾","author":"贯休","dynasty":"唐","verses":["世病如山岳，世医皆拱手。","道病如金锁，师遭锁锁否。","伊昔芙蓉颊，谈经似主涉。","苏合昼氤氲，天花似飞蝶。","觉树垂实，魔辈刺疾。","病也不问，终不皴膝。","春光冉冉，不上尔质。","东风浩浩，谩入尔室。","云何斯人，而有斯疾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-59841f8a-df17-4d9d-99b8-3b447d3cc54a","tags":[]},{"id":"poem-ed7400b219349a04489a0405","title":"淡黄柳·空城晓月","author":"姜夔","dynasty":"宋","verses":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-134","tags":["宋词三百首"]},{"id":"poem-ed8d75739721af15c25f9830","title":"送李侍御入茅山采药","author":"张南史","dynasty":"唐","verses":["苦县家风在，茅山道录传。","聊听骢马使，却就紫阳仙。","江海生岐路，云霞入洞天。","莫令千岁鹤，飞到草堂前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a5311d52-89f9-4ab0-a879-234456f23778","tags":[]},{"id":"poem-ed96477ed95d8dd695002c98","title":"念佛子","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、旦)穷秀才，夫和妇，为士马逃难登途。","望相怜，壮士略放一路。","［众］捉住。","枉自说闲言语。","买路钱留下金珠，稍迟延，便教你身丧须臾。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2956","tags":[]},{"id":"poem-ed9f699cda0d010f51865214","title":"正朝上左相张燕公","author":"杨重玄","dynasty":"唐","verses":["岁去愁终在，春还命不来。","长吁问丞相，东阁几时开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-603c3920-60eb-470b-820b-b6488c18441e","tags":[]},{"id":"poem-edaa9dee07654a51aa76ffdb","title":"甘州子·红炉深夜醉调笙","author":"顾敻","dynasty":"五代","verses":["红炉深夜醉调笙，敲拍处，玉纤轻。","小屏古画岸低平，烟月满闲庭。","山枕上，灯背脸波横。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-45","tags":[]},{"id":"poem-edb7c75bd1600f72ebf5a110","title":"柳枝辞十二首  其八","author":"徐铉","dynasty":"宋","verses":["柳岸烟昏醉里归，不知深处有芳菲。","重来已见花飘尽，唯有黄鶑啭树飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-45092445-09ad-44be-95cf-70073d45a49c","tags":[]},{"id":"poem-edb83a693c9e7dd4bceeb5e4","title":"离别难·花谢水流倏忽","author":"柳永","dynasty":"宋","verses":["花谢水流倏忽，嗟年少光阴。","有天然、蕙质兰心。","美韶容、何啻值千金。","便因甚、翠弱红衰，缠绵香体，都不胜任。","算神仙、五色灵丹无验，中路委瓶簪。","人悄悄，夜沈沈。","闭香闺、永弃鸳衾。","想娇魂媚魄非远，纵洪都方士也难寻。","最苦是、好景良天，尊前歌笑，空想遗音。","望断处，杳杳巫峰十二，千古暮云深。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-170","tags":[]},{"id":"poem-edbb9acc50ca3b3ee74c4932","title":"昔昔盐二十首 水溢芙蓉沼","author":"赵嘏","dynasty":"唐","verses":["渌沼春光后，青青草色浓。","绮罗惊翡翠，暗粉妬芙蓉。","云遍窗前见，荷翻镜里逢。","将心托流水，终日渺无从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-941c324b-08d0-4ecf-9ee7-62d71dd86afd","tags":[]},{"id":"poem-edc084930c973d9b5efdc2ad","title":"别宜春赴举","author":"卢肇","dynasty":"唐","verses":["秋天草木正萧疎，西望秦关别旧居。","筵上芳樽今日酒，箧中黄卷古人书。","辞乡且伴衔芦雁，入海终为戴角鱼。","长短九霄飞直上，不教毛羽落空虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8159f17b-e5dd-4f1c-8347-cc576023ab17","tags":[]},{"id":"poem-edc3e917a21d06e1704be86d","title":"西归","author":"晁端中","dynasty":"宋","verses":["安得龙山潮，驾回马河水。","水从楼前来，中有美人泪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b6bad12e-fd66-4afb-847e-b4e840c5e74f","tags":[]},{"id":"poem-edc64324e16456d632a7a9f8","title":"过金鸡石","author":"吕从庆","dynasty":"唐","verses":["金鸡自天来，桑麻列青眼。","群耳无一聪，昂冠复飞返。","遗音此寂然，千秋意何限。","所幸一片石，犹在田中坂。","我来抚弄之，襟怀日以散。","寄语埘中禽，尔徒博飧饭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-80463774-9228-48dd-8cc9-bc56bf43278a","tags":[]},{"id":"poem-edd2cce6c994196db5bdac7c","title":"山中依韵答刘书记见赠","author":"李山甫","dynasty":"唐","verses":["幽居少人事，三径草不开。","隐几虚室静，闲云入坐来。","至道非内外，讵言才不才。","宝月当秋空，高洁无纤埃。","心灭百虑减，诗成万象回。","亦有吾庐在，寂寞旧山隈。","从容未归去，满地生青苔。","谢公寄我诗，清奇不可陪。","白云飞不尽，碧云欲成堆。","惊风出地户，虩虩似震雷。","吟哦山岳动，令人心胆摧。","思君览章句，还复如望梅。","慷慨追古意，旷望登高台。","何当陶渊明，远师劝倾杯。","流年将老来，华髪自相催。","野寺连屏障，左右相裴回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-00746ae5-6e74-4285-954e-536bc25747ae","tags":[]},{"id":"poem-eddd1eb1092c6f5e5d86f14a","title":"又和八日","author":"徐铉","dynasty":"宋","verses":["微云疏雨淡新秋，晓梦依稀十二楼。","故作别离应有以，拟延更漏共无由。","那教人世长多恨，未必天仙不解愁。","博望苑中残酒醒，香风佳气独迟留。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ec2704b8-2120-4f29-8127-9588d479fef0","tags":[]},{"id":"poem-ede6bfbd5081c7d9a6b6675b","title":"赠五老韩尊师","author":"赵嘏","dynasty":"唐","verses":["有客斋心事玉晨，对山须鬓绿无尘。","住山道士年如鹤，应识当时五老人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-459acb00-3fd5-4061-9c51-d7d3fcd73699","tags":[]},{"id":"poem-edf60c88d63d8a9e95b60ab9","title":"游虞山顶维摩院","author":"周才","dynasty":"宋","verses":["西风近重阳，青女作奇酿。","高人事幽讨，木落秋可望。","山溪步屈曲，策以九节杖。","林空眼界宽，云深开法藏。","欢迎杂钟鼓，舞跃骇龙象。","载酒得良友，灵山拉寻访。","同来八九辈，俱能尚疏旷。","具馔击红鲜，折花泛新酿。","修竹当翠袖，泉声代清唱。","徘徊欲尽欢，更上层巅上。","要知本色人，方具六通相。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d5ea90d3-5425-44be-bf82-8c0291c3237c","tags":[]},{"id":"poem-edff53aa85aeab59590660c5","title":"鹧鸪天·本是瑶台月里仙","author":"崔敦礼","dynasty":"宋","verses":["本是瑶台月里仙。","笑麾鸾鹤住人间。","蟠桃一熟三千岁，剩对春风日月闲。","缡绶结，彩衣斑。","孙枝相应傍门阑。","年年同上长生酒，得见沧溟几度干。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-405","tags":[]},{"id":"poem-ee029a4182a4825bb2888898","title":"地僻","author":"赵崇嶓","dynasty":"宋","verses":["地僻逢迎少，吾生信杳冥。","清谈养生论，兀坐太玄经。","性拙贫逾乐，神清梦数灵。","亭亭岁寒友，相对眼终青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-837f73d0-4585-453e-9a46-1b8826888059","tags":[]},{"id":"poem-ee02ce658d17356b31ff683f","title":"郊庙歌辞 享太庙乐章 永和三章 一","author":"张说","dynasty":"唐","verses":["肃九室，谐八音。","歌皇慕，动神心。","礼宿设，乐妙寻。","声明备，[祼]奠临。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-712d4015-f37f-4b13-9445-f14daa6586fd","tags":[]},{"id":"poem-ee05ce741249d5bd63845ba0","title":"楚妃叹","author":"张籍","dynasty":"唐","verses":["湘云初起江沉沉，君王遥在云梦林。","江南雨多旌旗暗，台下朝朝春水深。","章华殿前朝万国，君心独自无终极。","楚兵满地能逐禽，谁用一身骋筋力。","西江若飜云梦中，麋鹿死尽应还宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e884efcb-d9c0-48b5-95b3-e644dba54b9b","tags":[]},{"id":"poem-ee06c7a79d15520dcbc759ec","title":"花舞·贵客之名从此有","author":"史浩","dynasty":"宋","verses":["贵客之名从此有。","多谢风流，飞驭陪尊酒。","持此一卮同劝后。","愿花长在人长寿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-22","tags":[]},{"id":"poem-ee0b118c59cf80c9f0c854f8","title":"次韵项君玉","author":"王琮","dynasty":"宋","verses":["惠然乘兴访幽栖，细雨冥冥湿杖藜。","七尺身强于鹤瘦，一生心不向人低。","日寻灵药行寒麓，时有新诗付小奚。","欲解貂金同一醉，酒垆闻只在前溪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6a0b3494-69f8-4e7b-af18-db3c603a1f36","tags":[]},{"id":"poem-ee114e85760e4465a391fd89","title":"因学人问事","author":"义存","dynasty":"唐","verses":["佗事佗人断，己事己自裁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-28037648-e19c-4519-9e74-c01b57e6e221","tags":[]},{"id":"poem-ee12563aa98d5f0ada00fa71","title":"句","author":"林杰","dynasty":"唐","verses":["金盘摘下挂朱颗，红壳开时饮玉浆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-903bd047-49ab-401d-a07f-4c62095f3dca","tags":[]},{"id":"poem-ee19635b6cf1b22cd16bb5a0","title":"迁村居二首 一","author":"李洞","dynasty":"唐","verses":["移居入村宇，树阙见城隍。","云水虽堪画，恩私不可忘。","猿涎滴鹤氅，麈尾拂僧床。","弃逐随樵牧，何由报稻粱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9097e41b-17a5-4c09-b333-9b151c31dec8","tags":[]},{"id":"poem-ee20d8bbad32f88b2333887c","title":"大环着","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(众)因孩儿出路，因孩儿出路，打猎沙陀，偶见林中白兔跷蹊。","若非他引见母，怎能够夫妻相会？前生里今日奇，从此团圆永效于飞。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8998","tags":[]},{"id":"poem-ee354eab85c519afbd397647","title":"越溪春·三月十三寒食日","author":"欧阳修","dynasty":"宋","verses":["三月十三寒食日，春色遍天涯。","越溪阆苑繁华地，傍禁垣、珠翠烟霞。","红粉墙头，秋千影里，临水人家。","归来晚驻香车。","银箭透窗纱。","有时三点两点雨霁，朱门柳细风斜。","沈麝不烧金鸭冷，笼月照梨花。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-754","tags":[]},{"id":"poem-ee35e45da42194a548b3f2c2","title":"菩萨蛮·归鸿声断残云碧","author":"李清照","dynasty":"宋","verses":["归鸿声断残云碧。","背窗雪落炉烟直。","烛底凤钗明。","钗头人胜轻。","角声催晓漏。","曙色回牛斗。","春意看花难。","西风留旧寒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-688","tags":[]},{"id":"poem-ee3ad0abff5ed4b7d2d3b834","title":"长相思·要相忘","author":"吕本中","dynasty":"宋","verses":["要相忘。","不相忘。","玉树郎君月艳娘。","几回曾断肠。","欲下床。","却上床。","上得床来思旧乡。","北风吹梦长。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-737","tags":[]},{"id":"poem-ee3e0c583c1683fa7817cbeb","title":"小苑春望宫池柳色","author":"崔绩","dynasty":"唐","verses":["帝京春气早，御柳已先荣。","嫩叶随风散，浮光向月明。","悠扬生别意，断续引芳声。","积翠连驰道，飘花出禁城。","柔条依水弱，远色带烟轻。","南望龙池畔，斜光照晚晴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5878fe4c-3613-461b-ab7e-1444dd2492f8","tags":[]},{"id":"poem-ee41a0a03df0569257d948a1","title":"拂霓裳·庆生辰","author":"晏殊","dynasty":"宋","verses":["庆生辰。","庆生辰是百千春。","开雅宴，画堂高会有诸亲。","钿函封大国，玉色受丝纶。","感皇恩。","望九重、天上拜尧云。","今朝祝寿，祝寿数，比松椿。","斟美酒，至心如对月中人。","一声檀板动，一炷蕙香焚。","祷仙真。","愿年年今日、喜长新。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-537","tags":[]},{"id":"poem-ee4246c1d5ccb2fe658ecdce","title":"同明府章送沈秀才还石门山读书","author":"皎然","dynasty":"唐","verses":["身为郢令客，心许楚山云。","文墨应经世，林泉漫诱君。","欲随樵子去，惜与道流分。","肯谢申公辈，治诗事汉文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e7a61698-8744-4ba7-ad8e-6e8aae32456e","tags":[]},{"id":"poem-ee4333df44dfb327431dae03","title":"侍宴赋得归雁","author":"徐铉","dynasty":"宋","verses":["夜静群动息，翩翩一雁归。","清音天际远，寒影月中微。","何处云同宿，长空雪共飞。","阳和常借便，免与素心违。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c0494ab5-f7e3-44ca-8560-9447eaf891eb","tags":[]},{"id":"poem-ee4b281c564484042820d5df","title":"偈颂六十七首  其二九","author":"释原妙","dynasty":"宋","verses":["低头觅天，仰面寻地。","波波挈挈，远之远矣。","蓦然撞著徐十三郎，嗄，元来只在遮里。","在遮里，腊月三十日到来，也是开眼见鬼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-57381fc8-a1ba-49e0-9d79-edfc6001f210","tags":[]},{"id":"poem-ee4cc14d5aeb68033e1f042e","title":"文献太子挽歌辞五首  其一","author":"徐铉","dynasty":"宋","verses":["国有承祧重，人知秉哲尊。","清风来望苑，遗烈在东藩。","此日升缑岭，何因到寝门。","天高不可问，烟霭共昏昏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-fce875ba-50c2-4b80-b04a-3d77c0b1e411","tags":[]},{"id":"poem-ee4d0685605b1cf8f6d392b9","title":"杜鹃行","author":"司空曙","dynasty":"唐","verses":["古时杜宇称望帝，魂作杜鹃何微细。","跳枝窜叶树木中，抢翔瞥捩雌随雄。","毛衣惨黑自顦顇，众鸟安肯相尊崇。","隳形不敢栖华屋，短翮唯愿巢深丛。","穿皮啄朽觜欲秃，苦饥始得食一虫。","谁言养雏不自哺，此语亦足为愚蒙。","声音咽哕若有谓，号啼略与婴儿同。","口干垂血转迫促，似欲上诉于苍穹。","蜀人闻之皆起立，至今相效传遗风。","乃知变化不可穷，岂知昔日居深宫，嫔妃左右如花红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-90ebf7a8-e3e4-4f50-8f66-fe0f412398c2","tags":[]},{"id":"poem-ee4efadf22832e438835faca","title":"雁儿落","author":"杨景贤","dynasty":"元","verses":["紫袈裟金缕轻，白锡杖银光净。","四天王执宝幢，八菩萨敲金磬。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3409","tags":[]},{"id":"poem-ee55e1739992fc7e50495e88","title":"满庭芳·爱日轻融","author":"史浩","dynasty":"宋","verses":["爱日轻融，阴云初敛，一番雪意阑珊。","柳摇金缕，梅绽五腮寒。","知是东皇翠葆，飞星汉、来止人间。","开新宴，笙歌逗晓，和气满城寰。","风光，偏舜水，贤侯政美，棠荫多欢。","更圜扉草鞠，木索长闲。","休向今朝惜醉，红妆映、群玉颓山。","相将见，宜春帖子，清夜写金銮。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-52","tags":[]},{"id":"poem-ee6248678f3d6e1da557b9dd","title":"柴门","author":"杜甫","dynasty":"唐","verses":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ae472a2c-7977-4ed6-a893-7ef7c3136666","tags":[]},{"id":"poem-ee77799c5960e869468f124d","title":"鼓笛令·见来两个宁宁地","author":"黄庭坚","dynasty":"宋","verses":["见来两个宁宁地。","眼厮打、过如拳踢。","恰得尝些香甜底。","苦杀人、遭谁调戏。","腊月望州坡上地。","冻著你、影亸村鬼。","你但那些一处睡。","烧沙糖、管好滋味。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-782","tags":[]},{"id":"poem-ee7ef4b1eabcf0584b8bd5d4","title":"边城独望","author":"马戴","dynasty":"唐","verses":["聊凭危堞望，倍起异乡情。","霜落蒹葭白，山昏雾露生。","河滩胡鴈下，戎垒汉鼙惊。","独树残秋色，狂歌泪满缨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0e88cd12-cf15-4c60-8963-1fa3ea435686","tags":["思乡"]},{"id":"poem-ee86eda1baffdc1da488e317","title":"七娘子引","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生上)蒙君不弃我身寒，今日里喜结良缘。","(旦上)一朵奇花今有主，姻缘感谢苍天。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8837","tags":[]},{"id":"poem-ee8ade2caaefd02c7f99e072","title":"应天长·双眉淡薄藏心事","author":"牛峤","dynasty":"五代","verses":["双眉淡薄藏心事，清夜背灯娇又醉。","玉钗横，山枕腻，宝帐鸳鸯春睡美。","别经时，无限意，虚道相思憔悴。","莫信彩笺书里，赚人肠断字。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-9","tags":[]},{"id":"poem-ee8d07dda35bb5632fe8a3e1","title":"送柳秀才往连州看弟","author":"马戴","dynasty":"唐","verses":["离人非逆旅，有弟谪连州。","楚雨沾猨暮，湘云拂鴈秋。","蒹葭行广泽，星月棹寒流。","何处江关鏁，风涛阻客愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b3154fb8-f95e-47b4-87ab-43e9226c839a","tags":[]},{"id":"poem-ee92acd37bb6a4c484c0608b","title":"山中寡妇","author":"杜荀鹤","dynasty":"唐","verses":["夫因兵乱守蓬茅，麻苎裙衫鬓发焦。","桑柘废来犹纳税，田园荒尽尚征苗。","时挑野菜和根煮，旋砍生柴带叶烧。","任是深山最深处，也应无计避征徭。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-山中寡婦","tags":[]},{"id":"poem-eea4631c736a64682714e11f","title":"分岁","author":"释居简","dynasty":"宋","verses":["办得分年供，清哉亦称怀。","野槃均柿串，草具爨松钗。","指冷柑初破，灰红芋旋埋。","火边相枕藉，火尽又添柴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-dd7e74e1-d26a-4c93-85ec-a5da5d5fa308","tags":[]},{"id":"poem-eea7dc22dfc1d4a673532819","title":"感皇恩·池馆足名花","author":"程大昌","dynasty":"宋","verses":["池馆足名花，四时蔫馥。","就里梅春春到速。","周遭松竹，任是雪霜长绿。","总堪供寿乐，翻新曲。","别向心田，有般奇木。","依约灵椿共标目。","八千换历，才当一番春复。","莫乱春起处，醅浮玉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-235","tags":[]},{"id":"poem-eea85ca09f0890704d236e9a","title":"山居四景 岭云","author":"李纲","dynasty":"宋","verses":["玉洁烟轻一片深，飘然出岫本无心。","孤飞远映碧天去，也解重来为作霖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-328bb663-4393-4e3a-aabd-b81c9850c9a3","tags":[]},{"id":"poem-eeb20fdd637709436a202b26","title":"如梦令·昨夜雨疏风骤","author":"李清照","dynasty":"宋","verses":["昨夜雨疏风骤。","浓睡不消残酒。","试问卷帘人，却道海棠依旧。","知否。","知否。","应是绿肥红瘦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-685","tags":[]},{"id":"poem-eebf97e9c4167a6515dc75eb","title":"西江月·鱼兔若还入手","author":"张伯端","dynasty":"宋","verses":["鱼兔若还入手，自然忘却筌蹄。","渡河筏子上天梯。","到彼悉皆遗弃。","未悟须凭言说，悟来言说皆非。","虽然四句属无为。","此等何须脱离。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-990","tags":[]},{"id":"poem-eec45da8e52c42fe670d61fb","title":"伤彩饰","author":"苏拯","dynasty":"唐","verses":["朝见亦光彩，暮见亦光彩。","一旦风雨飘，十分无一在。","尔形才似削，尔貌不如昨。","本为是凡姿，谁教染丹雘。","虚饰片时间，天意以为恶。","物假犹如此，人假争堪作。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-56286f96-de44-48ef-aa70-35560c092656","tags":[]},{"id":"poem-eec6e1fd31a1f81b2f5d58da","title":"鸳鸯篇","author":"李德裕","dynasty":"唐","verses":["君不见昔时同心人，化作鸳鸯鸟。","和鸣一夕不暂离，交颈千年尚为少。","二月草菲菲，山樱花未稀。","金塘风日好，何处不相依？","既逢解佩游女，更值凌波宓妃。","精光摇翠盖，丽色映珠玑。","双影相伴，双心莫违。","淹留碧沙上，荡漾洗红衣。","春光兮宛转，嬉游兮未反。","宿莫近天泉池，飞莫近长洲苑。","尔愿欢爱不相忘，须去人间罗网远。","南有潇湘洲，且为千里游。","洞庭无苦寒，沅江多碧流。","昔为薄命妾，无日不含愁。","今为水中鸟，颉颃自相求。","洛阳女儿在青阁，二月罗衣轻更薄。","金泥文彩未足珍，画作鸳鸯始堪著。","亦有少妇破瓜年，春闺无伴独婵娟。","夜夜学织连枝锦，织作鸳鸯人共怜。","悠悠湘水滨，清浅漾初苹。","菖花发艳无人识，江柳逶迤空自春。","唯怜独鹤依琴曲，更念孤鸾隐镜尘。","愿作鸳鸯被，长覆有情人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-388be58f-85a2-452f-8b15-30d3a04ad2e9","tags":["洞庭湖"]},{"id":"poem-eed0c4dcc1cf3aecc7f41031","title":"东门之杨","author":"佚名","dynasty":"先秦","verses":["东门之杨，其叶牂牂。昏以为期，明星煌煌。","东门之杨，其叶肺肺。昏以为期，明星晢晢。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-139","tags":[]},{"id":"poem-eee3540600b0451dcb1e21dd","title":"送张忠州使君八兄二首  其一","author":"曾协","dynasty":"宋","verses":["邂逅江干不自期，坐倾谈屑看霏霏。","岂无清禁摛华地，只得名城衣锦归。","惜别定知双鬓换，问诗常恨寸心违。","目穷千里苍茫际，惟有樯乌向北飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b37a85c3-fcf3-4c32-8345-05cdf1c9f1dc","tags":[]},{"id":"poem-eee5b5c30510910f6f08ecee","title":"与刘三礼陈孝廉言志","author":"李咸用","dynasty":"唐","verses":["真宰无私造化均，年年分散月中春。","皆期早蹑青云路，谁肯长为白社人。","宋国高风休敛翼，圣朝公道易酬身。","大须审固穿杨箭，莫遣参差鬓雪新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-125cba28-01d4-43f8-b9b1-acdfb4f82e0d","tags":[]},{"id":"poem-eee85442bb6519b487af3864","title":"偈颂三十首  其二六","author":"释印肃","dynasty":"宋","verses":["善者多魔自古今，佛魔一体只空心。","心迷不觉悭成贼，心悟回头便舍金。","莫怪迷心心怕贼，贼心对面也难寻。","三途地狱因斯得，奉报须防仁不仁。","不是道人先注脚，免他来喜去沈吟。","一年三百六十日，梦想颠倒不曾息。","耳闻眼见善庵名，更莫邪言喧戏剧。","思量生死大惊神，唯了本心称第一。","暂时忽听本无心，解脱沉沦千万亿。","寄语诸人莫蹈虚，勾阑不稳莫稍依。","莫令堕入深坑下，未免先当说与伊。","来往任观心不住，声香味触且随时。","孤峰独特谁为伴，尘世忙然我道奇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5e55c027-e5e6-4c91-9551-7d57e5923afe","tags":[]},{"id":"poem-eeea16ffbb56104a33856ac4","title":"句","author":"单氏","dynasty":"宋","verses":["帝王师不得，日月老应难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-15d8de72-bb95-49a1-9ccc-e472e9fa5711","tags":[]},{"id":"poem-eeefce83a225486e10a5ca19","title":"句","author":"崔幢","dynasty":"唐","verses":["寒气乍凝空有露，秋风不动水无波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-01bdc025-acc0-44bb-a543-556f4968d943","tags":[]},{"id":"poem-eef407db1467a3ba7b9baf46","title":"开岁连日有阴雨  其一","author":"孙嵩","dynasty":"宋","verses":["老杜诗章五百年，为吾替写早春篇。","恰从元日逾人日，重有阴阴冷落天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-fe101163-bf4b-4e6f-bb52-561fbc3d179e","tags":[]},{"id":"poem-eefaa82ca654ba9b2d8d0304","title":"戮后主出降诗","author":"王仁裕","dynasty":"唐","verses":["蜀朝昏主出降时，衔璧牵羊倒系旗。","二十万军高拱手，更无一个是男儿。","（涵芬楼排印本《说郛》卷三十四《豪异秘纂》引王仁裕《蜀石》。","）（按：此诗《鉴诫录》卷五《徐后事》谓王承旨作，《后山诗话》则以为花蕊夫人作，文字略异。","《全唐诗》卷七九八收花蕊名下，另注「一作蜀臣王承旨诗」。","《全唐诗续补遗》卷十七据《鉴诫录》收归王承旨。","今检《说郛》所引，与《鉴诫录》所载较相似，而于此诗作者，则云为「兴圣太子随军仁裕」。","王仁裕初仕前蜀，尝随侍王衍作诗，蜀亡入洛，仕后唐。","《说郛》所载可从，今为移正。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-10729560-27b1-4513-93e6-688956213ea2","tags":[]},{"id":"poem-ef051c386b479c5da6b48bac","title":"唐明堂乐章 迎送王公","author":"则天皇后","dynasty":"唐","verses":["千官肃事，万国朝宗。","载延百辟，爰集三宫。","君臣德合，鱼水斯同。","睿图方永，周历长隆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f9ad1795-2a0b-4397-8589-cb53fb7f65f1","tags":[]},{"id":"poem-ef07c5645787e182bed165e7","title":"北归昼渡海风便波平尤觉奇绝成五绝句  其五","author":"李纲","dynasty":"宋","verses":["平生奔走畏江湖，暮齿来乘海上桴。","自哂井蛙真见小，望洋向若一卢胡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-420b4e18-fd97-4022-b97f-9493842a6b60","tags":[]},{"id":"poem-ef12ab21a8f1cef950f19b40","title":"霜叶飞·断烟离绪","author":"吴文英","dynasty":"宋","verses":["断烟离绪。","关心事，斜阳红隐霜树。","半壶秋水荐黄花，香西风雨。","纵玉勒、轻飞迅羽。","凄凉谁吊荒台古。","记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。","聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。","小蟾斜影转东篱，夜冷残蛩语。","早白发、缘愁万缕。","惊飙从卷乌纱去。","漫细将、茱萸看，但约明年，翠微高处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-3","tags":["宋词三百首"]},{"id":"poem-ef1ea5babbc651e0d1b7ceed","title":"赠镜湖处士方干二首 二","author":"曹松","dynasty":"唐","verses":["秪拟应星眠越绝，唯将丽什当高勋。","磨砻清浊人难会，织络虚无帝亦闻。","鸟道未知山足雨，渔家已没镜中云。","他时莫为三徴起，门外沙鸥解笑君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9b79b3b7-65f4-4447-b261-71104bc2c748","tags":[]},{"id":"poem-ef2a0398e19aa989231bc89b","title":"寄张阶州","author":"徐铉","dynasty":"宋","verses":["仪甫秉忠信，神明自来舍。","绛灌虽不容，蛮貊皆从化。","荣名任纷纠，道性常闲暇。","传语当途人，无为劳叹咤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6df50e89-c133-4aa9-9f6f-92e8c204298c","tags":[]},{"id":"poem-ef2a7aa0707064fb00b1d1c5","title":"薄媚令","author":"无名氏《张协状元》","dynasty":"元","verses":["愁多怨极，历尽万千滋味。","幸几日身安免虑。","(旦上接)听得旁来，无事使奴暗喜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2527","tags":[]},{"id":"poem-ef2ea0f1058cba887b0f3f4b","title":"胡笳十八拍 第十四拍","author":"李纲","dynasty":"宋","verses":["大麦干枯小麦黄，问谁腰镰胡与羌。","汉家战士三十万，此岂有意仍腾骧。","安得突骑只五千，长驱东胡胡走藏。","近静潼关扫蝼蚁，为留猛士守未央。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a8db8276-860d-4ecb-9f8a-0b37e3116c54","tags":[]},{"id":"poem-ef2eccb321753ad62235c932","title":"次毕将叔韵寄寿阳三首  其二","author":"刘跂","dynasty":"宋","verses":["苦竹湓江宅，黄山秋浦亭。","猿声作头白，客泪对衫青。","笑尔悲凫胫，知吾寄水萍。","时时頼严尹，小队出郊坰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-67888377-07d1-420d-99ef-2855e47ebec7","tags":[]},{"id":"poem-ef357cf914c90f8c80b0443e","title":"遣兴二首 二","author":"赵嘏","dynasty":"唐","verses":["读彻残书弄水回，暮天何处笛声哀？花前独立无人会，依旧去年双燕来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8b8ddf58-7516-430c-b341-91a949972d97","tags":[]},{"id":"poem-ef3a3d15a2a1bf2830b432a0","title":"菩萨蛮·鸳鸯翡翠同心侣","author":"向子𬤇","dynasty":"宋","verses":["鸳鸯翡翠同心侣。","惊风不得双飞去。","春水绿西池。","重期相见时。","长怜心共语。","梦里池边路。","相见不如新。","花应解笑人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-769","tags":[]},{"id":"poem-ef434cd187518af2f6de399f","title":"与王楚同登青龙寺上方","author":"李益","dynasty":"唐","verses":["连冈出古寺，流睇移芳䜩。","鸟没汉诸陵，草平秦故殿。","摇光浅深树，拂木参差燕。","春心断易迷，远目伤难徧。","壮日各轻年，暮年方自见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0635bc3b-9aab-41e0-92d9-9fee8a31a838","tags":[]},{"id":"poem-ef4db9343f046e9d23e5bf09","title":"奉敕陪内宴","author":"王孝廉","dynasty":"唐","verses":["海国来朝自远方，百年一醉谒天裳。","日宫座外何攸见，五色云飞万岁光。","（见金毓黻撰集《渤海国志长编》卷十八引《文华秀丽集》上。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-538a7b02-b5b7-4c3a-a150-7bfcf2ee3e78","tags":[]},{"id":"poem-ef50f2ca5db0421144eba60d","title":"咏方圆动静","author":"李泌","dynasty":"唐","verses":["方如行义，圆如用智。","动如逞才，静如遂意。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-126eccee-4aa4-47d4-b207-0d3c36a7ec51","tags":[]},{"id":"poem-ef51396d4159b6bd37bc5284","title":"和立斋抱膝吟三章  其一","author":"王柏","dynasty":"宋","verses":["帝腹加顽足，上干天象速。","造膝论当世，从容金殿旭。","人生莫不有行藏，谁把行藏较短长。","要识行藏无所为，时哉出处总辉光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a12322d6-f43f-45cb-b696-3b62cfacf06e","tags":[]},{"id":"poem-ef54ca5ef311c5ec8299cc03","title":"偈颂 三","author":"文偃","dynasty":"唐","verses":["康氏圆形滞不明，魔深虚丧击寒冰。","凤羽展时超碧汉，晋锋八博拟何凭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-32d1dc8a-3042-4489-910e-9864a3d59bfc","tags":[]},{"id":"poem-ef557be9d8f162feb30927e8","title":"好事近·归日指清明","author":"葛立方","dynasty":"宋","verses":["归日指清明，肯把话言轻食。","已是飞花时候，赖东风无力。","青帘沽酒送春归，莫惜万金掷。","屈指明年春事，有红梅消息。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-542","tags":[]},{"id":"poem-ef56686bd84f4b11f7bbdf45","title":"郊庙歌辞 周郊祀乐章 武舞乐","author":"不详","dynasty":"唐","verses":["圭瓒方陈礼，干旄乃象功。","成文非羽籥，猛势若罴熊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ae1d49cc-efe9-4014-ad98-8417fedced83","tags":[]},{"id":"poem-ef5c451517ad181a1ec92cf3","title":"浣溪沙·康乐亭前种此君","author":"张孝祥","dynasty":"宋","verses":["康乐亭前种此君。","重来风月苦留人。","儿童竹马笑谈新。","今代孟士仍好客，政成归去眷方新。","十眉环坐晚妆匀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-360","tags":[]},{"id":"poem-ef5e8d7771e4a4df06a892df","title":"四","author":"王梵志","dynasty":"唐","verses":["好事须相让，恶事莫相堆。","（「堆」，伯二八四二卷作「推」。","）{亻|口/工}（郑校本作「但」。","）能辨此意，祸去福招来。","（「招来」，斯三三九三卷作「将来」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c43baa05-5165-41b3-855e-92d5ae4e8824","tags":[]},{"id":"poem-ef5f440d10383c09c14cab5c","title":"好事近·帘外五更风","author":"纳兰性德","dynasty":"清","verses":["帘外五更风，消受晓寒时节。","刚剩秋衾一半，拥透帘残月。","争教清泪不成冰。","好处便轻别。","拟把伤离情绪，待晓寒重说。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-62","tags":[]},{"id":"poem-ef69c8330df178a365cb96b0","title":"胡捣练·小桃花与早梅花","author":"晏殊","dynasty":"宋","verses":["小桃花与早梅花，尽是芳妍品格。","未上东风先拆。","分付春消息。","佳人钗上玉尊前，朵朵秾香堪惜。","谁把彩豪描得。","免恁轻抛掷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-500","tags":[]},{"id":"poem-ef76abefc47424c7ca6c9c75","title":"古意","author":"崔国辅","dynasty":"唐","verses":["红荷楚水曲，彪炳烁晨霞。","未得两回摘，秋风吹却花。","时芳不待妾，玉珮无处夸。","悔不盛年时，嫁与青楼家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d324e92c-f390-46f6-805e-f1dcd7e81f71","tags":[]},{"id":"poem-ef7f50abae3fa88e6e1e2017","title":"敦煌廿咏（并序） 十一、贞女台咏[二三]","author":"敦煌人作品[一]","dynasty":"唐","verses":["贞女谁家女？","孤标坐[二四]此台。","青蛾随月转[二五]，红粉向花开。","二八无人识，千秋已作灰。","洁身终不嫁，非为乏良媒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6c16caf8-8249-466e-bebc-da5c0bb937b1","tags":[]},{"id":"poem-ef7fe7627ef00bb745fed0a8","title":"郊庙歌辞 享节愍太子庙乐章 迎俎酌献","author":"不详","dynasty":"唐","verses":["嘉荐有典，至诚莫骞。","画梁云亘，雕俎星连。","乐器周列，礼容备宣。","依稀如在，若未宾天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0ff5fdc0-c751-4486-badb-b915f2846d71","tags":[]},{"id":"poem-ef800c8972676a667918853f","title":"金陵五题 乌衣巷","author":"刘禹锡","dynasty":"唐","verses":["朱雀桥边野草花，乌衣巷口夕阳斜。","旧时王谢堂前燕，飞入寻常百姓家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4fa92777-9bd6-45ca-9272-bac30459cf5e","tags":["唐诗三百首","怀古","七言绝句","带有地名","地名"]},{"id":"poem-ef84122bc8fa5fc32b8ae8f9","title":"酬张少府","author":"王维","dynasty":"唐","verses":["晚年唯好静，万事不关心。","自顾无长策，空知返旧林。","松风吹解带，山月照弹琴。","君问穷通理，渔歌入浦深。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-65e9c24b-bdbd-4ef9-9e14-012c8fde79b8","tags":["唐诗三百首","赠别","友情","规劝","五言律诗"]},{"id":"poem-ef849e329122b40f725fce23","title":"白云溪","author":"吴巩","dynasty":"唐","verses":["山径入修篁，深林蔽日光。","夏云生嶂远，瀑水引溪长。","秀迹逢皆胜，清芬坐转凉。","回看玉樽夕，归路赏前忘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f2e748c2-1c0f-4325-81dd-46e71e875e3f","tags":[]},{"id":"poem-ef8719ffca34ea38d1261dfe","title":"载见","author":"佚名","dynasty":"先秦","verses":["载见辟王，曰求厥章。龙旗阳阳，和铃央央。鞗革有鸧，休有烈光。率见昭考，以孝以享。","以介眉寿，永言保之，思皇多祜。烈文辟公，绥以多福，俾缉熙于纯嘏。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-282","tags":[]},{"id":"poem-ef8c6bcfebe83a9af1de2cff","title":"偈颂（幷序○序为南岳齐己撰） 三十二","author":"居遁","dynasty":"唐","verses":["凡有含生共一尘，先圣精勤早出伦。","彼既丈夫我亦尔，谁遣他春我不春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3cedf130-5eb4-46f0-afcc-13fe178c6f8e","tags":["衡山"]},{"id":"poem-ef90b594992365549b1ab0d5","title":"唐昌公主院看花","author":"司空曙","dynasty":"唐","verses":["遗殿空长闭，乘鸾自不回。","至今荒草上，寥落旧花开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-852b6ae2-62ae-486b-b236-dd51254e743a","tags":[]},{"id":"poem-ef96c1877773a6f13bc9c83c","title":"秋暑憩多景楼","author":"米芾","dynasty":"宋","verses":["纵目天容旷，披襟海共开。","山光随眦到，云景渡江来。","世界惭双足，生涯付一杯。","横风多景梦，应似穆王台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b1b1ebce-1937-4c11-95e0-15784945efaa","tags":[]},{"id":"poem-efa00d64cadb4a43a7a309ce","title":"和主司王起","author":"张道符","dynasty":"唐","verses":["三开文镜继芳声，暗暗云霄接去程。","会压洪波先得路，早升清禁共垂名。","莲峰对处朱轮贵，金榜传时玉韵成。","更许下才听白雪，一枝今过郄诜荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4922f871-64de-47b8-b45c-dee50d277f28","tags":[]},{"id":"poem-efa16799d8daeea79f5d5fad","title":"陪窦侍御灵云南亭宴诗得雷字","author":"高适","dynasty":"唐","verses":["人幽宜眺听，目极喜亭台。","风景知愁在，关山忆梦回。","秪言殊语默，何意忝游陪。","连唱波澜动，冥搜物象开。","新秋归远树，残雨拥轻雷。","簷外长天尽，尊前独鸟来。","常吟塞下曲，多谢幕中才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-829d9dfd-b384-4d00-a13e-dd8bd1beb5e5","tags":[]},{"id":"poem-efa1ebed45a1fd6d33ad0c59","title":"归云领","author":"陈岩","dynasty":"宋","verses":["飞云蔼蔼出从龙，遍为山村办岁丰。","雨到足时云自敛，有功及物不言功。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-36b96976-cdb5-4a6a-8fe9-1e1bf02d82b9","tags":[]},{"id":"poem-efad54df67763306f8854f6d","title":"卜算子","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外上］从别女孩儿，心下常萦系。","昨日令人去请归，彼此心欢喜。","雪隐鹭鸶飞始见？柳藏鹦鹉语方知。","昨日着李成去搬取王亲妈、秀才与我女孩儿同家另居。","待李成回来，便知分晓。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8124","tags":[]},{"id":"poem-efae27f50bff5b1a0378f027","title":"送僧入幽州","author":"贯休","dynasty":"唐","verses":["高士高无敌，腾腾话入燕。","无人知尔意，向我道非禅。","栗迳穿蕃冢，狼声隔远烟。","槃山多道侣，应未有归年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6bfb6de0-ca15-4efb-a45d-a40f1000ed32","tags":[]},{"id":"poem-efb837b60bc28f785799bc55","title":"泛永嘉江日暮回舟","author":"张子容","dynasty":"唐","verses":["无云天欲暮，轻鹢大江清。","归路烟中远，回舟月上行。","傍潭窥竹暗，出屿见沙明。","更值微风起，乘流丝管声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e2ed4537-3fcb-40ef-8c0f-29c1c46366b3","tags":[]},{"id":"poem-efbad1127f933943c83e150e","title":"哭丁千崖教授","author":"赵文","dynasty":"宋","verses":["一览楼头笑拂衣，今朝何意此歔欷。","断无痛饮歌都护，那得重归见令威。","太学废来同舍尽，清江好在故人非。","我来岂是无情者，为哭妻儿无泪挥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8f641eba-e8ef-4f43-b041-1d9a674544b1","tags":[]},{"id":"poem-efbe07c6358259bf4496df12","title":"关中送别","author":"薛能","dynasty":"唐","verses":["一行千里外，几事寸心间。","才子贫堪叹，男儿别是闲。","黄河淹华岳，白日照潼关。","若值乡人问，终军贱不还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-02096dd9-1734-4358-81f0-98ce21febd85","tags":["黄河"]},{"id":"poem-efe466bd51e42264d820737d","title":"好事近·日绎五千言","author":"程大昌","dynasty":"宋","verses":["日绎五千言，未说年龄可续。","且得襟期萧散，远氛嚣宠辱。","鬓须白尽秀眉生，来伴老眸绿。","人道雪霜林里，有翠松鲜竹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-231","tags":[]},{"id":"poem-efe93ad5807ddaf80beff3be","title":"望江南・忆江南·歌席上","author":"周邦彦","dynasty":"宋","verses":["歌席上，无赖是横波。","宝髻玲珑敧玉燕，绣巾柔腻掩香罗。","人好自宜多。","无个事，因甚敛双蛾。","浅淡梳妆疑见画，惺忪言语胜闻歌。","何况会婆娑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-465","tags":[]},{"id":"poem-efec6311b0d6890d1b47b8a6","title":"和晋陵陆丞早春游望","author":"韦应物","dynasty":"唐","verses":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光照绿苹。","忽闻歌苦调，归思欲沾巾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b67ddf05-43fb-4859-a1a9-34f95d45aabf","tags":["春天","唐诗三百首","伤怀","和诗","思乡","五言律诗"]},{"id":"poem-eff67ba44fd1116d366b3c7d","title":"次韵陆子高","author":"陈造","dynasty":"宋","verses":["一从别君来，圆缺几望舒。","相与兄弟然，异姓殊厥居。","向来帆归船，欲去仍趦趄。","平安可但已，拟凭双鲤鱼。","两地邈千里，二年能几书。","了知故人意，记忆犹勤渠。","当君访甓社，值我留南徐。","参辰巧相避，终冀或起予。","扣户听剥啄，果尔不作疎。","属者久契阔，兹焉不踌躇。","甚欲挽袖留，扣子万卷储。","子家老嗣宗，三赋陵相如。","阿戎青出蓝，万壑赴归墟。","宸廷奉大对，百韫财一纾。","有偕仲补衮，无取辛引裾。","俯视汉诸公，彼馁此有余。","置之不吾即，欲刃捐礛䃴。","南台复西掖，高位为谁虚。","未须芹藻地，脱口鎗珮琚。","平时交游间，别酒惯搀袪。","如君可畏敬，且复同乡闾。","求全待补劓，涉险资闲舆。","滔滔多面朋，著眼增欷歔。","视我若浼然，于君何頼与。","愿言风谊重，暇计日月除。","许寻十日盟，妙论穷终初。","治具有赤脚，抄诗戒小胥。","安得方角轮，一昔生君车。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-046d2d6e-e9f4-4215-8925-a1c044e687d8","tags":[]},{"id":"poem-eff7fac6d1bc9555a7322b25","title":"都人士","author":"佚名","dynasty":"先秦","verses":["彼都人士，狐裘黄黄。其容不改，出言有章。行归于周，万民所望。","彼都人士，台笠缁撮。彼君子女，绸直如发。我不见兮，我心不说。","彼都人士，充耳琇实。彼君子女，谓之尹吉。我不见兮，我心苑结。","彼都人士，垂带而厉。彼君子女，卷发如虿。我不见兮，言从之迈。","匪伊垂之，带则有余。匪伊卷之，发则有旟。我不见兮，云何盱矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-224","tags":[]},{"id":"poem-f004229c6c39a37f33a526dc","title":"野有蔓草","author":"佚名","dynasty":"先秦","verses":["野有蔓草，零露漙兮。有美一人，清扬婉兮。邂逅相遇，适我愿兮。","野有蔓草，零露瀼瀼。有美一人，婉如清扬。邂逅相遇，与子偕臧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-93","tags":[]},{"id":"poem-f009b8aff8be892c8844e5d8","title":"北京留守王太师挽歌词二首  其一","author":"司马光","dynasty":"宋","verses":["卢肇时推重，终军众共贤。","何如夺标日，未及弃𦈡年。","官历清涂徧，名居美事先。","人间福有五，视履岂非全。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-9ce8eeeb-688d-419a-8437-7a35ccf64b58","tags":[]},{"id":"poem-f00e1f055c479dbc9c4acf77","title":"访羊尊师","author":"孙革","dynasty":"唐","verses":["松下问童子，言师采药去。","只在此山中，云深不知处。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-162eb552-a496-4979-87e2-e441847d4e6f","tags":["唐诗三百首","五言绝句","写人","寻访"]},{"id":"poem-f0138a22509d3fb0592ca07a","title":"浣溪沙·容易浓香近画屏","author":"纳兰性德","dynasty":"清","verses":["容易浓香近画屏，繁枝影著半窗横。","风波狭路倍怜卿。","未接语言犹怅望，才通商略已懵腾。","只嫌今夜月偏明。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-57","tags":[]},{"id":"poem-f021a8f053af9661519fc09c","title":"贼平后送人北归","author":"司空曙","dynasty":"唐","verses":["世乱同南去，时清独北还。","他乡生白发，旧国见青山。","晓月过残垒，繁星宿故关。","寒禽与衰草，处处伴愁颜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4c745990-657a-41fe-ba2c-d9cf371ca563","tags":["唐诗三百首","酬赠","感伤","五言律诗"]},{"id":"poem-f0342b8ee16783a08e0277fa","title":"送潘述宏词下第归江外","author":"李端","dynasty":"唐","verses":["唱高人不和，此去泪难收。","上国经年住，长江满目流。","弈棋知胜偶，射策请焚舟。","应是田囗囗，玄成许尔游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c427bc24-14a9-4fdb-8801-ead203ab9fa2","tags":["长江"]},{"id":"poem-f03d9103e805ce0431ab5944","title":"茂陵山行陪韦金部","author":"李端","dynasty":"唐","verses":["宿雨朝来歇，空山秋气清。","盘云双鹤下，隔水一蝉鸣。","古道黄花落，平芜赤烧生。","茂陵虽有病，犹得伴君行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6805e578-f4a7-4cf3-9010-6aa77700dd2c","tags":[]},{"id":"poem-f0414b4a3c3e41616f164c10","title":"唐昌观看花","author":"张籍","dynasty":"唐","verses":["新红旧紫不相宜，看觉从前两月迟。","更向同来诗客道，明年到此莫过时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-833f4a39-0f62-420f-8033-870d5e243d7e","tags":[]},{"id":"poem-f04674873b7fe79fd97bd7f8","title":"同韩侍郎秋朝使院","author":"张南史","dynasty":"唐","verses":["重门启曙关，一叶报秋还。","露井桐柯湿，风庭鹤翅闲。","忘情簪白笔，假梦入青山。","惆怅祗应此，难裁语默间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6fa1dc58-6378-4da2-9b04-640aa565ab05","tags":[]},{"id":"poem-f04e9c8690f075b25f3077eb","title":"丹阳行","author":"孙逖","dynasty":"唐","verses":["丹阳古郡洞庭阴，落日扁舟此路寻。","传是东南旧都处，金陵中断碧江深。","在昔风尘起，京都乱如毁。","双阙戎虏间，千门战场里。","传闻一马化为龙，南渡衣冠亦愿从。","石头横帝里，京口拒戎锋。","青枫林下回天跸，杜若洲前转国容。","都门不见河阳树，辇道唯闻建业钟。","中原悠悠几千里，欲扫欃枪未云已。","英雄倾夺何纷然，一盛一衰如逝川。","可怜宫观重江里，金镜相传三百年。","自从龙见圣人出，六合车书混为一。","昔年王气今何在，并向长安就尧日。","荆榛古木闭荒阡，共道繁华不复全。","赤县唯余江树月，黄图半入海人烟。","暮来山水登临遍，览古愁吟泪如霰。","唯有空城多白云，春风淡荡无人见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-288c52fa-ce01-48c7-ae4a-760381fef23f","tags":["洞庭湖"]},{"id":"poem-f04ef0a54aa85215b57737e0","title":"与国贤良夜歌二首 二","author":"张柬之","dynasty":"唐","verses":["杏间花照灼，楼上月裴回。","带娇移玉柱，含笑捧金杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-425fe4c2-d80b-461b-b7ad-4cb8b865400e","tags":[]},{"id":"poem-f0554b4d7f4cd653fc2435f9","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑］筵间，绣巾莫围环，奇珍摆列，浑如洞府仙寰，美食嘉肴，堪并凤髓龙肝。","簪翠竹同乐同欢，饮绿醑齐歌齐唱。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8031","tags":[]},{"id":"poem-f05cc08542204d50f6b0a0e3","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["谔谔能昌唯唯亡，亦由匡正得贤良。","一从忠谠无周舍，吾过何人为短长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-70140c53-4f33-4335-9f15-c3be5b58cc52","tags":[]},{"id":"poem-f05f1d97424578110113b909","title":"七夕","author":"卢殷","dynasty":"唐","verses":["河耿月凉时，牵牛织女期。","欢娱方在此，漏刻竟由谁。","定不嫌秋驶，唯当乞夜迟。","全胜客子媍，十载泣生离。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3f4e80c2-593c-4273-aff7-4fe977f6dcf4","tags":[]},{"id":"poem-f0605fcfabc7759c85339bc2","title":"再入道场纪事应制","author":"广宣","dynasty":"唐","verses":["南方归去再生天，内殿今年异昔年。","见辟乾坤新定位，看题日月更高悬。","行随车辇登仙路，坐近炉烟讲法筵。","自喜恩深陪侍从，两朝长在圣人前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ad79561a-2047-4894-b9cc-b0d0db7e384d","tags":[]},{"id":"poem-f061b609d4b9793afe034675","title":"和白都官见赠","author":"司马光","dynasty":"宋","verses":["齿疏鬓白两眸昏，万事无堪老病身。","脱粟犹沾太仓禄，法官仍忝外台臣。","直缘迂僻求闲地，岂是孤高慕古人。","英俊满朝皆稷契，太山何少一飞尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a72e7b41-6cf6-42c0-a3d3-d9d3a6ba401d","tags":[]},{"id":"poem-f073a2de26426f357c941f95","title":"柳含烟·御沟柳","author":"毛文锡","dynasty":"五代","verses":["御沟柳，占春多。","半出宫墙婀娜，有时倒影蘸轻罗，曲尘波。","昨日金銮巡上苑，风亚舞腰纤软。","栽培得她近皇宫，瑞烟浓。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-20","tags":[]},{"id":"poem-f07417da243795d5faa4a438","title":"题独醒小亭","author":"王琮","dynasty":"宋","verses":["退食多留此，翛然一散襟。","凉从晓来觉，秋向雨中深。","墙竹侵山色，簷茅杂柳阴。","有谁能载酒，过我共幽寻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-27128583-9de6-444b-b0c5-61e6b6954333","tags":[]},{"id":"poem-f07452faf0591c6cafb6cd1b","title":"春秋战国门 郭开","author":"周昙","dynasty":"唐","verses":["秦袭邯郸岁月深，何人沾赠郭开金。","廉颇还国李牧在，安得赵王为尔擒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-84e7dad7-4cb9-448b-bbb7-d7e543859aa4","tags":[]},{"id":"poem-f096d9620685daacd74d4d39","title":"忆汉月·红杏一枝遥见","author":"杜安世","dynasty":"宋","verses":["红杏一枝遥见。","凝露粉愁香怨。","吹开吹谢任春风，恨流莺、不能拘管。","曲池连夜雨，绿水上、碎红千片。","直拟移来向深院。","任凋零、不孤双眼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-949","tags":[]},{"id":"poem-f09a6128ef69d8e53552b31e","title":"后庭花·莺啼燕语芳菲节","author":"毛熙震","dynasty":"五代","verses":["莺啼燕语芳菲节，瑞庭花发。","昔时欢宴歌声揭，管弦清越。","自从陵谷追游歇，画梁尘黦。","伤心一片如圭月，闲锁宫阙。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-5","tags":[]},{"id":"poem-f0a0ab3c9fce2129058c589e","title":"六么令·绿阴春尽","author":"晏几道","dynasty":"宋","verses":["绿阴春尽，飞絮绕香阁。","晚来翠眉宫样，巧把远山学。","一寸狂心未说，已向横波觉。","画帘遮币。","新翻曲妙，暗许闲人带偷掏。","前度书多隐语，意浅愁难答。","昨夜诗有回纹，韵险还慵押。","都待笙歌散了，记取留时霎。","不消红蜡。","闲云归后，月在庭花旧阑角。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-31","tags":["宋词三百首"]},{"id":"poem-f0b9ecbca86c583cbca02be5","title":"咏史诗 牛渚","author":"胡曾","dynasty":"唐","verses":["温峤南归辍棹晨，燃犀牛渚照通津。","谁知万丈洪流下，更有朱衣跃马人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ed4dcc77-2f07-4ce2-b2ce-18acf8fe4d02","tags":[]},{"id":"poem-f0bbcd0c7a9197f8342c02f4","title":"起居帖","author":"杨凝式","dynasty":"唐","verses":["行住坐卧处，手摩胁与肚，心腹通快时，两手肠下踞。","踞之彻膀腰，背拳摩肾部。","才觉力倦来，即使家人助。","行之不厌频，昼夜无穷数，岁久积功成，渐入神仙路。","（见明刻本朱存理辑《铁网珊瑚·书品》卷一。","）（按：诗后题云：「干祐元年冬残腊暮，华阳焦上人尊师处传，杨凝式。","」又附米友仁跋云：「右杨凝式书神仙起居法八行，臣米友仁鉴定真迹跋。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-373fe4b1-af0a-4e65-bd79-d517c610720d","tags":[]},{"id":"poem-f0bc2ae3038f32edc522230a","title":"无题","author":"李商隐","dynasty":"唐","verses":["相见时难别亦难，东风无力百花残。","春蚕到死丝方尽，蜡炬成灰泪始干。","晓镜但愁云鬓改，夜吟应觉月光寒。","蓬山此去无多路，青鸟殷勤为探看。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ed79f9bc-d5d1-4251-b22d-d091e0758a3f","tags":["唐诗三百首","思念","七言律诗","八年级下册(课外)","初中古诗","爱情"]},{"id":"poem-f0bdedeb1822d573814ed85d","title":"石人","author":"释居简","dynasty":"宋","verses":["面冷如水瘦，心刚笑竹虚。","痕云衣不浣，晕藓髻难梳。","七凿混沌死，十成山泽癯。","谷城山下路，谁复理残书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1a867255-e8cd-420a-a6c2-72fc3f5fb37f","tags":[]},{"id":"poem-f0cfad459265b3f3cd18d103","title":"重赠邢校书","author":"李益","dynasty":"唐","verses":["俱从四方事，共会九秋中。","断蓬与落叶，相值各因风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1e649844-ac06-47a4-96a7-baa2db22ea1b","tags":[]},{"id":"poem-f0d2dd7fba27001628f0a7be","title":"句  其四","author":"谭用之","dynasty":"宋","verses":["眠云无限好知己，应笑不归花满樽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3e2a21b8-4b55-4955-a984-8d305323db7e","tags":[]},{"id":"poem-f0dcc8c352e18e8012d6d059","title":"句","author":"钱元瓘","dynasty":"唐","verses":["别泪已多红蜡泪，离杯须满绿荷杯。","（《两浙金石志》卷四和凝《大晋故天下兵马都元帅守尚书令吴越国王谥文穆钱公神道碑》引。","）（〖1〗《钱公神道碑》：「天福六年，王以弟兄归任，丝竹张筵，因抒嘉篇，久吟警句。","〖诗略〗诗罢酒阑，情伤疾作。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6a7ab35b-8b96-48f3-9083-bd2190867ad4","tags":[]},{"id":"poem-f0e02bf74b8ec39b22b55cd0","title":"初发扬子寄元大校书","author":"韦应物","dynasty":"唐","verses":["凄凄去亲爱，泛泛入烟雾。","归棹洛阳人，残钟广陵树。","今朝此为别，何处还相遇。","世事波上舟，沿洄安得住。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-5b3a5651-2a80-4fb1-b1bf-c9fb5ec38905","tags":["唐诗三百首","离别","五言古诗","依恋"]},{"id":"poem-f0e56212fc300f58fb29c5d6","title":"小游仙诗九十八首 七十六","author":"曹唐","dynasty":"唐","verses":["彤阁钟鸣碧鹭飞，皇君催熨紫霞衣。","丹房玉女心慵甚，贪看投壶不肯归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8b56272f-fb13-42c9-90a1-f5f302e67e35","tags":[]},{"id":"poem-f0e57f573f8ba7289bfcb6bc","title":"近试上张籍水部","author":"朱庆余","dynasty":"唐","verses":["洞房昨夜停红烛，待晓堂前拜舅姑。","[妆]罢低声问夫壻，画眉深浅入时无。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-27ff54ab-4861-43d8-b3c1-69113d2e4e10","tags":["唐诗三百首","新婚","七言绝句","考试"]},{"id":"poem-f0e86d0f89caa52d39f2bf7e","title":"早春题湖上顾氏新居二首 一","author":"项斯","dynasty":"唐","verses":["近得水云看，门长侵早开。","到时微有雪，行处又无苔。","劝酒客初醉，留茶僧未来。","每逢晴暖日，唯见乞花栽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-43ee6f2a-01cc-44e1-a732-3a68788368bd","tags":[]},{"id":"poem-f0ea0e130ad03078148e3c9e","title":"追昔行","author":"薛逢","dynasty":"唐","verses":["朝光如飞犹尚可，暮更如箭不容卧。","犍为穿城更漏频，一一皆从枕边过。","一夕凡几更，一更凡几声。","青春枉向镜中老，白发虚从愁里生。","曾窥帝里东邻女，自比桃花镜中许。","一朝嫁得征戌儿，荷戈千里防秋去。","去时只作旦暮期，别后生死俱不知。","风惊粉色入蝉鬓，愁送镜花潜堕枝。","前年因出长安陌，见一女人头雪白。","日中扶杖憇树阴，髣髴形容认相识。","向予吁嗟还独语，曾与君家邻舍住。","当时妾嫁与征人，几向墙头诮夫主。","花开叶洛何推迁，屈指数当三十年。","眉头薤叶同枯叶，琴上朱弦成断弦。","嫁时宝镜依然在，鹊影菱花满光彩。","梦里长嗟离别多，愁中不觉颜容改。","叹息人生能几何，喜君颜貌未蹉跎。","因君下马重相顾，请奏青门肠断歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-06df66db-1a03-4b81-8be2-f0ab109bc66e","tags":[]},{"id":"poem-f0ecd7061ff7af755d8f2679","title":"野游","author":"延寿","dynasty":"唐","verses":["独步出衡茅，寒云著地交。","烧平多败穴，叶落见危巢。","（见南宋钱唐陈起《增广圣宋高僧诗选后集》卷中，《南宋群贤小集》第二十五册，嘉庆六年石门顾氏读画斋刊本。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8a2d25c1-74fe-43af-bff9-d62bac5c5c9e","tags":[]},{"id":"poem-f0f72a7889556f0a53207b3b","title":"卜居","author":"华镇","dynasty":"宋","verses":["桑弧蓬矢是男儿，故国松楸亦重违。","架搆自知惟壁立，绸缪谁敢羡翚飞。","桑麻地狭妻孥笑，堂庑簷低燕雀稀。","清世薄才何所用，求田问舍未应非。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-25004067-8dfc-4d2d-a70d-aa7224d8d2dc","tags":[]},{"id":"poem-f0f93df136db373064eac943","title":"闻大愿和尚顺世三首 一","author":"贯休","dynasty":"唐","verses":["王室今如毁，仍闻丧我师。","古容图得否，内院去无疑。","岳鬼月中哭，松龛雪次隳。","直须文五色，始可立高碑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f25f808d-b3dc-46a3-94f1-27d63e18543a","tags":[]},{"id":"poem-f0fa0e50982e823f778ebe68","title":"盛山十二诗 隐月岫","author":"韦处厚","dynasty":"唐","verses":["初映钩如线，终衔镜似钩。","远澄秋水色，高倚晓河流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d212cafa-6d47-405f-8e4d-00124c278927","tags":[]},{"id":"poem-f10416516cbb6c6569311f80","title":"同陈宰黄簿游灵山八首宰云吾辈可谓忙里偷闲苦中作乐以八字为韵  其八","author":"陈造","dynasty":"宋","verses":["吾侪自由身，声利为缠索。","不有山林幽，何以宽此缚。","熏炉仍茗椀，钩窗共盘礴。","何必覩史天，是中差可乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-46991cd9-e64a-48dc-abc9-31925b7a1e2d","tags":[]},{"id":"poem-f10952eea2429f8c117ed78e","title":"赠月洞先生","author":"叶碧峰","dynasty":"宋","verses":["跳出尘关百念轻，大元羽士宋儒生。","易参羲圣通玄妙，诗比唐人并驾行。","咒水洒时天地浄，符文书处鬼神惊。","洞中静夜天留月，心与梅花一样清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4f0eaf02-abaf-4a1d-8d2c-ede3b735e486","tags":[]},{"id":"poem-f10b5d74f18fa2654c8ada59","title":"咏史诗 五湖","author":"胡曾","dynasty":"唐","verses":["东上高山望五湖，雪涛烟浪起天隅。","不知范蠡乘舟后，更有功臣继踵无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c53cdcc4-2c29-435c-886f-6b6c7d4f644a","tags":[]},{"id":"poem-f10dc368725629d9b36122d1","title":"甘州・八声甘州·记玉关、踏雪事清游","author":"张炎","dynasty":"宋","verses":["记玉关、踏雪事清游。","寒气脆貂裘。","傍枯林古道，长河饮马，此意悠悠。","短梦依然江表，老泪洒西州。","一字无题处，落叶都愁。","载取白云归去，问谁留楚佩，弄影中洲。","折芦花赠远，零落一身秋。","向寻常野桥流水，待招来、不是旧沙鸥。","空怀感，有斜阳处，却怕登楼。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-258","tags":["宋词三百首"]},{"id":"poem-f11029f23aa1375a37171759","title":"清平乐·烟轻雨小","author":"纳兰性德","dynasty":"清","verses":["烟轻雨小，望里青难了。","一缕断虹垂树杪，又是乱山残照。","凭高目断征途，暮云千里平芜。","日夜河流东下，锦书应托双鱼。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-98","tags":[]},{"id":"poem-f114c883b366ca44a2279f51","title":"送臧子与子仪之楚州告免解二首  其二","author":"陈造","dynasty":"宋","verses":["昭代论豪杰，崔侯允武文。","小却折遐冲，厚用当致君。","敷政极中和，殖学根典坟。","士有砆玉岐，公自泾渭分。","何人非教育，二臧实不群。","两两计偕去，名犹壅上闻。","试袖于𫇭歌，往拜刘将军。","心醉公瑾前，何待曲糵醺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-666b18ff-c8e4-4c4b-a4a8-55000d7ec4df","tags":[]},{"id":"poem-f117b18c0f273b5c71a613ff","title":"诉衷情·春情满眼脸红绡","author":"魏承班","dynasty":"五代","verses":["春情满眼脸红绡，娇妒索人饶。","星靥小，玉珰摇，几共醉春朝。","别后忆纤腰，梦魂劳。","如今风叶又萧萧，恨迢迢。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-8","tags":[]},{"id":"poem-f11b35cada1fb9131ac2aae5","title":"送李端","author":"严维","dynasty":"唐","verses":["故关衰草遍，离别正堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","揜泣空相向，风尘何所期。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-67c18ea1-db49-44b5-8b21-6176e4a86416","tags":["唐诗三百首","冬天","友情","送别","五言律诗","伤怀"]},{"id":"poem-f120308c960064e0f15061d3","title":"生查子·霜寒月满窗","author":"蔡伸","dynasty":"宋","verses":["霜寒月满窗，夜永人无寐。","绛腊有馀情，偏照鸳鸯被。","看尽旧时书，洒尽今生泪。","衙鼓已三更，还是和衣睡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-967","tags":[]},{"id":"poem-f12755705eefdbf23669f38a","title":"偈","author":"永安","dynasty":"唐","verses":["汝问西来意，且过遮（《五灯会元》作「这」）边立。","昨夜三更时，雨打虚空湿。","电影豁（《五灯会元》作「忽」）然明，不似蚰蜒急。","（见《景德传灯录》卷二十六、《五灯会元》卷十。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d0dccdd7-3c91-4041-b3ea-dce0a7fa36bd","tags":[]}];
